module pipelined_addsub(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    input clk,
    input reset
);

reg [31:0] a_reg, b_reg, sum_reg;
reg carry_reg;
wire [31:0] xor_out;

assign xor_out = a_reg ^ b_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        a_reg <= 0;
        b_reg <= 0;
        sum_reg <= 0;
        carry_reg <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        if (sub) begin
            b_reg <= ~b + 1;
        end
        sum_reg <= xor_out + carry_reg;
        carry_reg <= (a_reg & b_reg) | (xor_out & carry_reg);
    end
end

assign sum = sum_reg;

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    input clk,
    input reset
);

wire [31:0] stage1_sum;
wire [31:0] stage2_sum;

pipelined_addsub stage1(
    .a(a),
    .b(b),
    .sub(sub),
    .sum(stage1_sum),
    .clk(clk),
    .reset(reset)
);

pipelined_addsub stage2(
    .a(stage1_sum),
    .b(32'b0),
    .sub(1'b0),
    .sum(stage2_sum),
    .clk(clk),
    .reset(reset)
);

assign sum = stage2_sum;

endmodule,"After synthesis, this design has 1 a21o_1, 3 a21oi_1, 5 a31oi_1, 3 and2_0, 1 and3_1, 6 and4_1, 167 clkinv_1, 162 dfrtp_1, 27 nand2_1, 2 nand2b_1, 6 nand3_1, 8 nand4_1, 16 nor2_1, 5 nor3_1, 6 nor4_1, 5 o21a_1, 10 o21ai_0, 8 o31ai_1, 1 o41ai_1, 1 or2_0, 1 or3_1, 6 or4_1, 76 xnor2_1, 37 xor2_1. ","Area of a21o_1 is 7.51. Area of a21oi_1 is 5.0. Area of a31oi_1 is 6.26. Area of and2_0 is 6.26. Area of and3_1 is 6.26. Area of and4_1 is 8.76. Area of clkinv_1 is 3.75. Area of dfrtp_1 is 25.02. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nand3_1 is 5.0. Area of nand4_1 is 6.26. Area of nor2_1 is 3.75. Area of nor3_1 is 5.0. Area of nor4_1 is 6.26. Area of o21a_1 is 7.51. Area of o21ai_0 is 5.0. Area of o31ai_1 is 7.51. Area of o41ai_1 is 8.76. Area of or2_0 is 6.26. Area of or3_1 is 6.26. Area of or4_1 is 7.51. Area of xnor2_1 is 8.76. Area of xor2_1 is 8.76.

