module adc_data_fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);

    parameter WIDTH = 12;
    parameter DEPTH = 16;

    input aclr;
    input [WIDTH-1:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [WIDTH-1:0] q;
    output rdempty;
    output wrfull;

    reg [DEPTH-1:0] wptr;
    reg [DEPTH-1:0] rptr;
    reg [WIDTH-1:0] mem [DEPTH-1:0];

    reg [WIDTH-1:0] q_reg;
    wire [WIDTH-1:0] q_next;

    assign rdempty = (wptr == rptr);
    assign wrfull = ((wptr + 1) % DEPTH == rptr);

    assign q_next = mem[rptr];

    always @(posedge aclr or posedge wrclk) begin
        if (aclr) begin
            wptr <= 0;
        end else if (wrclk & wrreq) begin
            mem[wptr] <= data;
            wptr <= (wptr + 1) % DEPTH;
        end
    end

    always @(posedge aclr or posedge rdclk) begin
        if (aclr) begin
            rptr <= 0;
        end else if (rdclk & rdreq & !rdempty) begin
            rptr <= (rptr + 1) % DEPTH;
        end
    end

    always @(posedge aclr or posedge rdclk) begin
        if (aclr)
            q_reg <= 0;
        else if (rdclk & rdreq & !rdempty)
            q_reg <= q_next;
    end

    assign q = q_reg;

endmodule,"After synthesis, this design has 1 a211oi_1, 3 a21boi_0, 5 a21oi_1, 4 a221oi_1, 36 a222oi_1, 4 a22o_1, 27 a22oi_1, 4 a31oi_1, 1 a41oi_1, 2 and4_1, 4 and4b_1, 20 clkinv_1, 20 dfrtp_1, 192 dfxtp_1, 192 mux2_1, 25 nand2_1, 3 nand2b_1, 17 nand3_1, 1 nand3b_1, 9 nand4_1, 26 nor2_1, 4 nor3_1, 2 nor4_1, 5 nor4b_1, 6 nor4bb_1, 4 o22a_1, 1 or3_1, 1 or4_1, 11 xnor2_1, 2 xor2_1. ","Area of a211oi_1 is 7.51. Area of a21boi_0 is 7.51. Area of a21oi_1 is 5.0. Area of a221oi_1 is 8.76. Area of a222oi_1 is 10.01. Area of a22o_1 is 8.76. Area of a22oi_1 is 7.51. Area of a31oi_1 is 6.26. Area of a41oi_1 is 8.76. Area of and4_1 is 8.76. Area of and4b_1 is 10.01. Area of clkinv_1 is 3.75. Area of dfrtp_1 is 25.02. Area of dfxtp_1 is 20.02. Area of mux2_1 is 11.26. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nand3_1 is 5.0. Area of nand3b_1 is 7.51. Area of nand4_1 is 6.26. Area of nor2_1 is 3.75. Area of nor3_1 is 5.0. Area of nor4_1 is 6.26. Area of nor4b_1 is 8.76. Area of nor4bb_1 is 10.01. Area of o22a_1 is 8.76. Area of or3_1 is 6.26. Area of or4_1 is 7.51. Area of xnor2_1 is 8.76. Area of xor2_1 is 8.76.

