module fsm #(
  parameter n = 4, // number of input signals
  parameter m = 2 // number of output signal
)(
  input [n-1:0] in,
  output reg [m-1:0] out
);

parameter s = 8; // number of states

reg [2:0] state; // state register

// Boolean functions for state transitions
always @ (posedge in[0]) begin
  case (state)
    3'b000: if (in[0]) state <= 3'b001; else state <= 3'b000;
    3'b001: if (in[1]) state <= 3'b011; else state <= 3'b010;
    3'b010: if (in[2]) state <= 3'b101; else state <= 3'b100;
    3'b011: if (in[3]) state <= 3'b111; else state <= 3'b110;
    3'b100: if (in[0]) state <= 3'b001; else state <= 3'b000;
    3'b101: if (in[1]) state <= 3'b011; else state <= 3'b010;
    3'b110: if (in[2]) state <= 3'b101; else state <= 3'b100;
    3'b111: if (in[3]) state <= 3'b111; else state <= 3'b110;
  endcase
end

// Binary encoding of each state
always @ (state) begin
  case (state)
    3'b000: out <= 2'b00;
    3'b001: out <= 2'b01;
    3'b010: out <= 2'b10;
    3'b011: out <= 2'b11;
    3'b100: out <= 2'b00;
    3'b101: out <= 2'b01;
    3'b110: out <= 2'b10;
    3'b111: out <= 2'b11;
  endcase
end

