module top_module(
    input wire clk,
    input wire reset,
    input wire [31:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [15:0] out_mux
);

    // 16-to-1 MUX
    reg [7:0] mux_in_0 = 0;
    reg [7:0] mux_in_1 = 0;
    wire [3:0] mux_sel = in[3:0];
    wire [7:0] mux_out;

    mux_16to1 mux_inst (
        .in_0(mux_in_0),
        .in_1(mux_in_1),
        .sel(mux_sel),
        .out(mux_out)
    );

    // 1-to-16 DEMUX
    wire [3:0] demux_sel = in[7:4];
    wire [15:0] demux_out;

    demux_1to16 demux_inst (
        .in(in[7:0]),
        .sel(demux_sel),
        .out(demux_out)
    );

    // Control Logic
    reg mux_enable = 0;
    reg demux_enable = 0;

    always @ (posedge clk) begin
        if (reset) begin
            mux_enable <= 0;
            demux_enable <= 0;
        end else begin
            if (select) begin
                mux_enable <= 1;
                demux_enable <= 0;
            end else begin
                mux_enable <= 0;
                demux_enable <= 1;
            end
        end
    end

    // Output Assignment
    assign out_mux = mux_out;
    assign out_hi = mux_enable ? mux_out : 8'b0;
    assign out_lo = demux_enable ? demux_out[demux_sel] : 8'b0;

endmodule
module mux_16to1(
    input [7:0] in_0,
    input [7:0] in_1,
    input [3:0] sel,
    output reg [7:0] out
);

    always @ (sel) begin
        case(sel)
            4'b0000: out <= in_0;
            4'b0001: out <= in_1;
            // add cases for 14 more inputs
            default: out <= 8'b0;
        endcase
    end

endmodule
module demux_1to16(
