module top_module(
    input clk,    // clock signal for the D flip-flops
    input [15:0] in,    // 16-bit input for the barrel shifters
    output reg [15:0] out    // 16-bit final output
);

    wire [7:0] out_left; // 8-bit output for the left side of the barrel shifters
    wire [7:0] out_right; // 8-bit output for the right side of the barrel shifters

    reg [7:0] in_left;    // 8-bit input for the left side of the barrel shifters
    reg [7:0] in_right;    // 8-bit input for the right side of the barrel shifters

    reg [15:0] temp;    // 16-bit temporary storage for the input

    // Barrel Shifters
    //instantiate the barrel shifters
    left_shifter left_bs(
        .in(in_left),
        .out(out_left)
    );

    right_shifter right_bs(
        .in(in_right),
        .out(out_right)
    );

    // Shift the data
    always @(*) begin
        in_left <= out_left;
        in_right <= out_right;
    end

    // D flip-flops for the final output
    always @(posedge clk) begin
        temp <= in;
        out <= temp;
    end

endmodule

module left_shifter(
    input [7:0] in,    // 8-bit input
    output reg [7:0] out    // 8-bit output
);

    always @(*) begin
        out = in << 1;    // shift the input left by 1 bit
    end

endmodule

module right_shifter(
    input [7:0] in,    // 8-bit input
    output reg [7:0] out    // 8-bit output
);

    always @(*) begin
        out = in >> 1;    // shift the input right by 1 bit
    end

endmodule
