			4'hb: branch_taken <= N ^ V;
			4'hc: branch_taken <= (N & ~Z & V ) | (~N & ~Z & ~V);
			4'hd: branch_taken <= (N ^ V) & ~Z;

			4'hf: branch_taken <= 1;
		endcase
