        .d(count[0])
    );

    DFF flipflop1 (
        .q(Q[1]),
        .clk(CLK),
        .d(count[1])
    );

    DFF flipflop2 (
        .q(Q[2]),
        .clk(CLK),
        .d(count[2])
    );

    DFF flipflop3 (
        .q(Q[3]),
        .clk(CLK),
        .d(count[3])
    );

    always @(posedge CLK) begin
