                cnv_next = 1'b0;

                sclk_next = 1'b1;
                count_next = 7'b1;
                state_next = STATE_READ;
            end

        end
        STATE_READ: begin
            state_next = STATE_READ;

            count_next = count_reg + 1;

            sclk_next = count_reg[0];

            if (sclk_reg == 1'b0) begin
                data_next = {data_reg[14:0], sdo};
            end

            if (count_reg == 7'h21) begin
                count_next = 7'b0;
                valid_next = 1'b1;
                state_next = STATE_IDLE;
            end
        end
    endcase
end

always @(posedge clk) begin
    if (~rstn) begin
        state_reg <= STATE_IDLE;

        data_reg <= 16'b0;
        valid_reg <= 1'b0;

        count_reg <= 7'b0;

        cnv_reg  <= 1'b0;
        sclk_reg <= 1'b1;

    end else begin
        state_reg <= state_next;

        data_reg <= data_next;
        valid_reg <= valid_next;

        count_reg <= count_next;

        cnv_reg  <= cnv_next;
        sclk_reg <= sclk_next;
    end
end


