module fifo #
(
  parameter WIDTH = 8, // data width
  parameter DEPTH = 16 // depth of the FIFO
)
(
  input clk,
  input reset,
  input wr_en,
  input rd_en,
  input [WIDTH-1:0] data_in,
  output reg [WIDTH-1:0] data_out,
  output reg full,
  output reg empty
);

  reg [(WIDTH+1):0] mem [0:DEPTH-1]; // memory array
  reg [$clog2(DEPTH+1):0] wr_ptr, rd_ptr; // write and read pointers (initialized to 0)

  // write operation
  always @(posedge clk) begin
    if (reset) begin
      wr_ptr <= 0;
    end else if (wr_en & !full) begin
      mem[wr_ptr][WIDTH-1:0] <= data_in;
      wr_ptr <= (wr_ptr + 1) % DEPTH;
    end
  end

  // read operation
  always @(posedge clk) begin
    if (reset) begin
      rd_ptr <= 0;
    end else if (rd_en & !empty) begin
      data_out <= mem[rd_ptr][WIDTH-1:0];
      rd_ptr <= (rd_ptr + 1) % DEPTH;
    end
  end

  // status flags
  reg [$clog2(DEPTH+1):0] count; // number of elements in the FIFO (initialized to 0)
  always @(posedge clk or negedge reset) begin
    if (!reset)
      count <= 0;
    else if (wr_en & !full)
      count <= count + 1;
    else if (rd_en & !empty)
      count <= count - 1;
  end
  always @* begin
    if (count == DEPTH) begin
      full <= 1;
    end else begin
      full <= 0;
    end
    if (count == 0) begin
      empty <= 1;
    end else begin
      empty <= 0;
    end
  end

