module traffic_light_controller (
  input clk,
  input reset,
  output reg red,
  output reg green,
  output reg yellow
);

  parameter RED = 2'b00;
  parameter GREEN = 2'b01;
  parameter YELLOW = 2'b10;

  reg [1:0] state = RED;
  reg [3:0] count = 4'b0000;

  always @(posedge clk) begin
    if (reset) begin
      state <= RED;
      count <= 4'b0000;
    end else begin
      case (state)
        RED: begin
          if (count == 4'b0101) begin
            state <= GREEN;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end

        GREEN: begin
          if (count == 4'b1010) begin
            state <= YELLOW;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end

        YELLOW: begin
          if (count == 4'b0010) begin
            state <= RED;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  always @(state) begin
    case (state)
      RED: begin
        red <= 1;
        green <= 0;
        yellow <= 0;
      end

      GREEN: begin
        red <= 0;
        green <= 1;
        yellow <= 0;
      end

      YELLOW: begin
        red <= 0;
        green <= 0;
        yellow <= 1;
      end
    endcase
  end

endmodule
