module fifo(
    input clk,
    input reset_n,
    input wr,
    input [7:0] wr_data,
    input rd,
    output reg [7:0] rd_data,
    output reg empty,
    output reg full,
    output reg almost_empty,
    output reg almost_full
    );

    reg [7:0] memory [1:0];
    reg [1:0] rd_address;
    reg [1:0] wr_address;
    reg [1:0] entries;
    wire full_wire;
    wire empty_wire;
    wire almost_full_wire;
    wire almost_empty_wire;

    assign full_wire = (entries == 2);
    assign empty_wire = (entries == 0);
    assign almost_full_wire = (entries == 1);
    assign almost_empty_wire = (entries == 1);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rd_address <= 2'b0;
            wr_address <= 2'b0;
            entries <= 2'b0;
        end else begin
            if (wr & !full) begin
                memory[wr_address] <= wr_data;
                wr_address <= (wr_address == 2'b1) ? 2'b0 : (wr_address + 1);
                entries <= entries + 1;
            end
            if (rd & !empty) begin
                rd_data <= memory[rd_address];
                rd_address <= (rd_address == 2'b1) ? 2'b0 : (rd_address + 1);
                entries <= entries - 1;
            end
        end
    end

    always @*
    begin
        full = full_wire;
        empty = empty_wire;
        almost_full = almost_full_wire;
        almost_empty = almost_empty_wire;
    end

