module binary_counter (
    input CLK, RST,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (RST) begin
            Q <= 4'b0000;
        end
        else begin
            if (Q == 4'b1111) begin
                Q <= 4'b0000;
            end
            else begin
                Q <= Q + 1;
            end
        end
    end

