	input  wire        RENDERER_SEL_BUFF,

input  wire [ 7:0] RENDERER_DATA ,
   output wire [18:0] RENDERER_ADDR ,
   output wire        RENDERER_WE   ,
   output wire        RENDERER_OE   ,
   output wire        RENDERER_CE   ,
