module shift_register_4bit(
    input clk,
    input reset,
    input load,
    input [3:0] data_in,
    output reg [3:0] data_out
);

// internal signals
reg [3:0] shift_reg;

// reset shift register to all zeros
always @ (posedge reset or posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else if (load) begin
        // load data on rising edge of clock
        shift_reg <= data_in;
    end else begin
        // shift data
        shift_reg <= {shift_reg[2:0], 1'b0}; // shift in a 0
        data_out <= shift_reg;
    end
end

