parameter IDLE = 2'b00, WRITE = 2'b01, RWAIT = 2'b10, BRESP_WAIT = 2'b11;
parameter BRESP_OKAY = 2'b00, BRESP_EXOKAY = 2'b01, BRESP_SLVERR = 2'b10, BRESP_DECERR = 2'b11;

