module checksum #(
  parameter n = 8 // number of data bits
)(
  input [n-1:0] data,
  output c
);


reg [n:0] sum;
reg [n-1:0] twos_comp;

// Compute the sum of the data bits
always @(*) begin
  sum = {1'b0, data} + 1'b0;
end

// Compute the two's complement of the sum
always @(*) begin
  twos_comp = ~sum + 1'b1;
end

// Output the checksum
assign c = twos_comp[n-1];

endmodule
