            current_state <= S1;
            next_count <= 4'b0001;
          end
        end
        S1: begin
          if (enable) begin
            current_state <= S2;
            next_count <= 4'b0010;
          end
        end
        S2: begin
          if (enable) begin
            current_state <= S3;
            next_count <= 4'b0011;
          end
        end
        S3: begin
          if (enable) begin
            current_state <= S0;
            next_count <= 4'b0000;
          end
        end
      endcase
    end
  end

  // Define output register and output logic
  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      count <= 4'b0000;
    end
    else begin
      if (current_state == S3 && next_count == COUNT_MAX) begin
        count <= 4'b0000;
      end
      else if (enable) begin
        count <= next_count;
      end
    end
  end

