module add_sub_32bit(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

wire [31:0] a_inv;
wire [31:0] b_inv;
wire carry_in;
wire carry_out;
wire [31:0] sum_temp;

assign carry_in = sub;

ripple_carry_adder adder(
    .a(a),
    .b(b_inv),
    .carry_in(carry_in),
    .carry_out(carry_out),
    .sum(sum_temp)
);

assign sum = sub ? ~sum_temp + 1 : sum_temp;

