  assign int_comp_wire = {|int_addr_reg, int_addr_reg < int_data_reg};

  always @*
  begin
    int_addr_next = int_addr_reg;
    int_case_next = int_case_reg;

    case(int_case_reg)
      2'd0:
      begin
        if(key_flag & int_comp_wire[0])
