module top_module (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    input select,
    output [7:0] OUT
);

reg [3:0] shift_reg;
wire [7:0] shifted_value;

barrel_shifter bs(
    .in(shift_reg),
    .out(shifted_value),
    .select(select)
);

always @(posedge CLK) begin
    if (RST) begin
        shift_reg <= 4'b0;
    end else if (LD) begin
        shift_reg <= D;
    end else begin
        shift_reg <= {shift_reg[2:0], shifted_value[0]};
    end
end

assign OUT = shifted_value | shift_reg;

endmodule

module barrel_shifter (
    input [3:0] in,
    output [7:0] out,
    input select
);

assign out = select ? {4'b0, in} : {in, 4'b0};

endmodule
