module top_module (
    input clk,
    input [2:0] d,
    output reg reset,
    output reg q,
    output reg w,
    output reg x,
    output reg y,
    output reg z
);

reg [1:0] d_ff;
wire and_out;

// Dual-edge triggered flip-flop
always @(posedge clk) begin
    if (~reset) begin
        d_ff <= 2'b0;
        q <= 1'b0;
    end else begin
        d_ff <= {d_ff[0], d[0]};
        q <= d_ff[1];
    end
end

// 2-to-1 multiplexer to select between the two D flip-flops output based on the clock edge
assign and_out = d_ff[0] & d_ff[1];

// 3-to-1 multiplexer to select between the three input bits for the 3-to-4 wire connection
always @(*) begin
    case (d)
        3'b000: begin
            w = 1'b1;
            x = 1'b0;
            y = 1'b0;
            z = 1'b0;
        end
        3'b001: begin
            w = 1'b0;
            x = 1'b0;
            y = 1'b0;
            z = 1'b1;
        end
        3'b010: begin
            w = 1'b0;
            x = and_out & ~d[2];
            y = and_out & d[2];
            z = 1'b0;
        end
        3'b011: begin
            w = 1'b0;
            x = 1'b0;
            y = 1'b1;
            z = 1'b0;
        end
        3'b100: begin
            w = 1'b0;
            x = 1'b0;
            y = 1'b0;
            z = 1'b0;
        end
        default: begin
            w = 1'b0;
            x = 1'b0;
            y = 1'b0;
            z = 1'b0;
        end
    endcase
end

// Active-high reset output
always @(posedge clk) begin
    reset <= (d == 3'b111);
end

