module johnson_counter (
    input clk,
    input rst_n,
    output wire [7:0] out
);

    reg [7:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 8'b00000000;
        end else begin
            case (state)
                8'b00000000: state <= 8'b10000000;
                8'b10000000: state <= 8'b11000000;
                8'b11000000: state <= 8'b11100000;
                8'b11100000: state <= 8'b11110000;
                8'b11110000: state <= 8'b11111000;
                8'b11111000: state <= 8'b11111100;
                8'b11111100: state <= 8'b11111110;
                8'b11111110: state <= 8'b11111111;
                8'b11111111: state <= 8'b01111111;
                8'b01111111: state <= 8'b00111111;
                8'b00111111: state <= 8'b00011111;
                8'b00011111: state <= 8'b00001111;
                8'b00001111: state <= 8'b00000111;
                8'b00000111: state <= 8'b00000011;
                8'b00000011: state <= 8'b00000001;
                8'b00000001: state <= 8'b00000000;
            endcase
        end
    end

