        case (state)
	        STATE_IDLE: begin
                done<=0;
                tx <= 1'b1;
                if(enable)begin
	    		    state <= STATE_START;
	    		    data <= dout;
	    		    bitpos <= 0;
                end
    	    end
    	    STATE_START: begin
    			tx <= 1'b0;
    			state <= STATE_DATA;
    	    end
    	    STATE_DATA: begin
    			if (bitpos == count-1)begin
