module spi (
    input wire clk,
    input wire resn,
    input wire trig,
    output wire done,
    output reg [15:0] rdData,
    input wire [15:0] wrData,

    // SPI interface
    output reg SCLK,
    output reg SS,
    output reg MOSI,
    input wire MISO
    );

   reg [3:0] state;
   reg [15:0] bitCount;
   reg [15:0] clkCounter;

   // Generate SPI clock
   // ADC operates from 0.8 to 3.2 MHz
   always @ (posedge clk) begin
      clkCounter = clkCounter + 1;
      if (clkCounter == 33) begin
         SCLK <= !SCLK;
      end
   end

   always @ (SCLK) begin
      if (!resn) begin
         SS <= 1;
         MOSI <= 0;
         state <= 0;
         bitCount <= 0;
      end else begin
         case (state)
           0: begin
              // Idle
              if (trig) begin
                 if (SCLK == 0) begin
                    // SS should be lowered on the first falling edge of SCLK
                    SS <= 0;
                    state <= 1;
                    bitCount <= 15;
                 end
              end
           end

           1: begin
              if (SCLK == 0) begin
                 // In order to avoid potential race conditions, the
                 // user should generate MOSI on the negative edges of SCLK.
                 MOSI <= wrData[bitCount];
                 bitCount <= bitCount - 1;
                 if (bitCount == 0) begin
                    state <= 2;
                 end
              end else begin
                 // Capture data bits on the rising edge of SCLK.
                 rdData[bitCount] <= MISO;
              end
           end

           2: begin
              if (SCLK == 1) begin
                 // SS should be raised on the last rising edge of an operational frame.
                 SS <= 1;
                 MOSI <= 0;
                 state <= 0;
                 bitCount <= 0;
              end
           end

           default: ;
         endcase
      end
   end

   assign done = SS;
endmodule,"After synthesis, this design has 1 a211oi_1, 11 a21oi_1, 8 a22oi_1, 4 a31oi_1, 2 and2_0, 1 and3_1, 2 and4_1, 8 clkinv_1, 17 dfxtp_1, 36 dlxtn_1, 24 nand2_1, 3 nand2b_1, 2 nand3_1, 2 nand4_1, 20 nor2_1, 4 nor2b_1, 3 nor3_1, 1 nor3b_1, 6 nor4_1, 4 o21a_1, 8 o21ai_0, 1 o21bai_1, 1 o31ai_1, 1 o41ai_1, 1 or2_0, 3 or3_1, 2 or4_1, 2 or4b_1, 12 xnor2_1, 7 xor2_1. ","Area of a211oi_1 is 7.51. Area of a21oi_1 is 5.0. Area of a22oi_1 is 7.51. Area of a31oi_1 is 6.26. Area of and2_0 is 6.26. Area of and3_1 is 6.26. Area of and4_1 is 8.76. Area of clkinv_1 is 3.75. Area of dfxtp_1 is 20.02. Area of dlxtn_1 is 15.01. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nand3_1 is 5.0. Area of nand4_1 is 6.26. Area of nor2_1 is 3.75. Area of nor2b_1 is 6.26. Area of nor3_1 is 5.0. Area of nor3b_1 is 7.51. Area of nor4_1 is 6.26. Area of o21a_1 is 7.51. Area of o21ai_0 is 5.0. Area of o21bai_1 is 7.51. Area of o31ai_1 is 7.51. Area of o41ai_1 is 8.76. Area of or2_0 is 6.26. Area of or3_1 is 6.26. Area of or4_1 is 7.51. Area of or4b_1 is 10.01. Area of xnor2_1 is 8.76. Area of xor2_1 is 8.76.

