    parameter CS_WIDTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire SCK,
    output reg [DATA_WIDTH-1:0] MOSI,
    input wire [DATA_WIDTH-1:0] MISO,
    input wire [CS_WIDTH-1:0] CS
);

