module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input add_sub_ctrl,
    input select,
    output [7:0] result,
    output overflow,
    output eq,
    output gt,
    output lt,
    output [7:0] max_value,
    output max_from_add_sub
);

    wire [7:0] add_sub_result;
    wire add_sub_overflow;
    wire [3:0] comp_result;
    wire comp_eq;
    wire comp_gt;
    wire comp_lt;

    add_sub add_sub_inst (
        .a(a),
        .b(b),
        .add_sub_ctrl(add_sub_ctrl),
        .result(add_sub_result),
        .overflow(add_sub_overflow)
    );

    comparator comparator_inst (
        .a(a[3:0]),
        .b(b[3:0]),
        .eq(comp_eq),
        .gt(comp_gt),
        .lt(comp_lt),
        .result(comp_result)
    );

    assign eq = (a == b);
    assign gt = (add_sub_ctrl == 1'b0) ? (add_sub_result[7] == 1'b0 && add_sub_result > b) : (a > b);
    assign lt = (add_sub_ctrl == 1'b0) ? (add_sub_result[7] == 1'b1 || add_sub_result < b) : (a < b);

    reg [7:0] _result;
    reg _overflow;
    reg [7:0] _max_value;
    reg _max_from_add_sub;

    always @(*) begin
        if (select == 1'b0) begin
            _result = add_sub_result;
            _overflow = add_sub_overflow;
        end else begin
            _result = comp_result;
            _overflow = 1'b0;
        end

        if (gt) begin
            _max_value = add_sub_result;
            _max_from_add_sub = 1'b1;
        end else begin
            _max_value = b;
            _max_from_add_sub = 1'b0;
        end

        if (comp_gt) begin
            _max_value = a;
            _max_from_add_sub = 1'b0;
        end
    end

    assign result = _result;
    assign overflow = _overflow;
    assign max_value = _max_value;
    assign max_from_add_sub = _max_from_add_sub;

endmodule
module add_sub (
    input [7:0] a,
    input [7:0] b,
    input add_sub_ctrl,
    output [7:0] result,
    output overflow
);

    assign result = (add_sub_ctrl == 1'b0) ? a + b : a - b;
    assign overflow = ((add_sub_ctrl == 1'b0 && a[7] != b[7] && result[7] != a[7]) || (add_sub_ctrl == 1'b1 && result[7] != a[7]));

endmodule
module comparator (
    input [3:0] a,
    input [3:0] b,
    output eq,
    output gt,
    output lt,
    output [3:0] result
);

    assign eq = (a == b);
    assign gt = (a > b);
    assign lt = (a < b);
    assign result = (gt) ? a : b;

