if(!rst)
  wen_0<=1'b0;
else
  wen_0<=wen;

always@(posedge clk or negedge rst)
if(!rst)
  wen_1<=1'b0;
else
  wen_1<=wen_0;

always@(posedge clk or negedge rst)
if(!rst)
  i_valid_0<=1'b0;
