module carry_select_adder(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum
);

    wire [31:0] p, g, c0, c1, c2, c3;

    assign p = a ^ b;
    assign g = a & b;

    assign c0 = cin;
    assign c1 = g[0] | (p[0] & c0);
    assign c2 = g[1] | (p[1] & c1);
    assign c3 = g[2] | (p[2] & c2);

    assign sum = p ^ cin ^ (g & {c3, c2, c1, c0});

