  // PWM counter
  if (pwm_counter == max_pwm_width) begin
    pwm_counter <= 0;
    pwm_out <= 0;
  end else if (pwm_counter < pwm_width) begin
    pwm_counter <= pwm_counter + 1;
    pwm_out <= 1;
  end else begin
    pwm_counter <= pwm_counter + 1;
    pwm_out <= 0;
  end

  // H-bridge direction
  if (dir == 0) begin
    hbridge_dir <= 1;
  end else begin
    hbridge_dir <= 0;
  end
end

