assign decoded_data_temp[1] = error ? (encoded_data_temp[4] ^ (error_position == 3'b010)) : encoded_data_temp[4];
assign decoded_data_temp[2] = error ? (encoded_data_temp[5] ^ (error_position == 3'b011)) : encoded_data_temp[5];
