module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [2:0] sel, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] q);

    // Counter module
    reg [3:0] count;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
        end else if (count == 4'b1111) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    // Multiplexer module
    wire [3:0] mux_out;
    mux_6to1 mux_inst (
        .sel(sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    // Control logic module
    reg [1:0] active_module;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            active_module <= 2'b00;
        end else begin
            case (sel)
                3'b000, 3'b001, 3'b010, 3'b011, 3'b100, 3'b101: active_module <= 2'b01; // Counter is active
                3'b110, 3'b111: active_module <= 2'b10; // Multiplexer is active
            endcase
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (active_module == 2'b01) begin
            q <= count;
        end else begin
            q <= mux_out;
        end
    end

endmodule

// 6-to-1 multiplexer module
module mux_6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out);

    always @(*) begin
        case (sel)
            3'b000: out <= data0;
            3'b001: out <= data1;
            3'b010: out <= data2;
            3'b011: out <= data3;
            3'b100: out <= data4;
            3'b101: out <= data5;
            3'b110, 3'b111: out <= data0 | data1 | data2 | data3 | data4 | data5; // Logical OR of all data inputs
        endcase
    end

