        .bin(binary_counter),
        .bcd_digit_0(bcd_digit_0),
        .bcd_digit_1(bcd_digit_1),
        .bcd_digit_2(bcd_digit_2),
        .bcd_digit_3(bcd_digit_3)
    );

    priority_encoder priority_encoder_inst (
        .bcd_digit_0(bcd_digit_0),
        .bcd_digit_1(bcd_digit_1),
        .bcd_digit_2(bcd_digit_2),
        .bcd_digit_3(bcd_digit_3),
        .ena(ena)
    );

    assign q = {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0};

