module binary_counter_16bit (
    input clk,
    input reset,
    output reg [15:0] q);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 16'd0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module binary_to_bcd (
    input [15:0] bin,
    output reg [3:0] bcd_digit_0,
    output reg [3:0] bcd_digit_1,
    output reg [3:0] bcd_digit_2,
    output reg [3:0] bcd_digit_3);

    integer i;

    always @(*) begin
        bcd_digit_0 = 4'd0;
        bcd_digit_1 = 4'd0;
        bcd_digit_2 = 4'd0;
        bcd_digit_3 = 4'd0;

        for (i = 0; i < 16; i = i + 1) begin
            if (bcd_digit_0 >= 5) begin
                bcd_digit_0 = bcd_digit_0 + 3;
            end
            if (bcd_digit_1 >= 5) begin
                bcd_digit_1 = bcd_digit_1 + 3;
            end
            if (bcd_digit_2 >= 5) begin
                bcd_digit_2 = bcd_digit_2 + 3;
            end
            if (bcd_digit_3 >= 5) begin
                bcd_digit_3 = bcd_digit_3 + 3;
            end

            {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0} = {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0} << 1;
            bcd_digit_0[0] = bin[15 - i];
        end
    end

endmodule

module priority_encoder (
    input [3:0] bcd_digit_0,
    input [3:0] bcd_digit_1,
    input [3:0] bcd_digit_2,
    input [3:0] bcd_digit_3,
    output reg [3:1] ena);

    always @(*) begin
        if (bcd_digit_3 != 4'd0) begin
            ena = 3'b001;
        end else if (bcd_digit_2 != 4'd0) begin
            ena = 3'b010;
        end else if (bcd_digit_1 != 4'd0) begin
            ena = 3'b100;
        end else begin
            ena = 3'b000;
        end
    end

