module top_module (
    input clk,
    input reset,
    input [7:0] data0,
    input [7:0] data1,
    input sel,
    output reg [7:0] out
);

reg [2:0] mux_sel;
wire [3:0] mux_out;
wire [7:0] and_out;

mux_selector mux_inst (
  .sel(mux_sel),
  .data0(data0[3:0]),
  .data1(data0[7:4]),
  .data2(data1[3:0]),
  .data3(data1[7:4]),
  .out(mux_out)
);

bitwise_and and_inst (
    .input1(mux_out),
    .input2(mux_out),
    .out(and_out)
);

always @(posedge clk) begin
    if (reset) begin
        mux_sel <= 3'b000;
        out <= 8'b00000000;
    end else begin
        mux_sel <= sel ? 3'b001 : 3'b000;
        out <= and_out;
    end
end

endmodule

module mux_selector (
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  output [3:0] out
);

reg [3:0] out_reg;
assign out = out_reg;

always @* begin
    case (sel)
        3'b000: out_reg = data0;
        3'b001: out_reg = data1;
        3'b010: out_reg = data2;
        3'b011: out_reg = data3;
        default: out_reg = 4'bxxxx;
    endcase
end

endmodule

module bitwise_and (
    input [3:0] input1,
    input [3:0] input2,
    output [7:0] out
);

assign out = input1 & input2;

endmodule
