module top_module (
    input clk,
    input reset,
    output [15:0] q
);
// Decoder module inputs
wire [1:0] select;
wire en;
// Square wave module outputs
wire out;
// Instantiate the modules
decoder_4to16 decoder (
    .select(select),
    .en(en),
    .out(q)
);
square_wave square (
    .clk(clk),
    .reset(reset),
    .out(out)
);
