module decoder_4to16 (
    input [1:0] select,
    input en,
    output [15:0] out
);
reg [15:0] out_reg;
always @ (select, en) begin
    if (en) begin
        case (select)
            2'b00: out_reg = 16'b0000000000000001;
            2'b01: out_reg = 16'b0000000000000010;
            2'b10: out_reg = 16'b0000000000000100;
            2'b11: out_reg = 16'b0000000000001000;
            default: out_reg = 16'b0000000000000000;
        endcase
    end else begin
        out_reg = 16'b0000000000000000;
    end
end
assign out = out_reg;
endmodule

module square_wave (
    input clk,
    input reset,
    output out
);
reg out_reg;
reg [31:0] counter;
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 0;
        out_reg <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 100000000) begin
            counter <= 0;
            out_reg <= ~out_reg;
        end
    end
end
assign out = out_reg;
endmodule
