module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] S,
    output Cout
);

wire [15:0] carry;
assign carry[0] = Cin;

genvar i;
generate
    for (i = 0; i < 15; i = i + 1) begin : full_adder
        full_adder_1bit FA (
            .A(A[i]),
            .B(B[i]),
            .Cin(carry[i]),
            .Cout(carry[i+1]),
            .S(S[i])
        );
    end
endgenerate

assign S[15] = A[15] ^ B[15] ^ carry[15];
assign Cout = carry[15];

endmodule

module full_adder_1bit (
    input A,
    input B,
    input Cin,
    output Cout,
    output S
);

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule
