			end
			POP_A: begin
				n_state = PUSH_ALU;
			end
			PUSH_ALU: begin
				n_state = IF;
			end
			PUSH_INST: begin
				n_state = IF;
			end
			POP_INST: begin
				n_state = IF;
			end
