module rx_DS_SE(
	input		d,
	input		s,
	input		rxClk,
	input		rxReset,

	output	[1:0]	dq,
	output		dqValid
);
	wire rxPhase = d ^ s;

	reg d_r, rxPhase_r;
	always @(posedge rxClk) begin
		if(rxReset) begin
			d_r <= 0;
			rxPhase_r <= 0;
		end
		else begin
			d_r <= d;
			rxPhase_r <= rxPhase;
		end
	end

	reg rxPhase_rr;
	always @(posedge rxClk) begin
		if(rxReset) begin
			rxPhase_rr <= 0;
		end
		else begin
			rxPhase_rr <= rxPhase_r;
		end
	end

	wire edgeDetect = rxPhase_r ^ rxPhase_rr;
	wire bit0Enable = edgeDetect & rxPhase_r;
	wire bit1Enable = edgeDetect & ~rxPhase_r;

	reg bit0_r, bit1_r;

	always @(posedge rxClk) begin
		if(rxReset) begin
			bit0_r <= 0;
			bit1_r <= 0;
		end
		else begin
			if(bit0Enable) begin
				bit0_r <= d_r;
			end

			if(bit1Enable) begin
				bit1_r <= d_r;
			end
		end
	end

	reg q0, q1, qen, qnfe;

	always @(posedge rxClk) begin
		if(rxReset) begin
			q0 <= 0;
			q1 <= 0;
			qen <= 0;
			qnfe <= 0;
		end
		else begin
			q0 <= bit0_r;
			q1 <= bit1_r;
			qen <= bit0Enable;
			qnfe <= qen | qnfe;
		end
	end

	assign dq = {q1, q0};
	assign dqValid = qen & qnfe;
endmodule

