    I2C_FSM_TimerPreset = 1'b1;
    I2C_FSM_TimerEnable = 1'b0;
    I2C_FSM_Wr1         = 1'b0;
    I2C_FSM_Wr0         = 1'b0;
    case (I2C_FSM_State)
      stIdle: begin
        if (QueryLocal_i == 1'b1)
        begin
          I2C_FSM_NextState = stReqLocWrPtr;
          I2C_Data_o        = 8'b10011000;
          I2C_FIFOWrite_o   = 1'b1;
        end
        else if (QueryRemote_i == 1'b1)
        begin
          I2C_FSM_NextState = stReqRemWrPtr;
          I2C_Data_o        = 8'b10011000;
          I2C_FIFOWrite_o   = 1'b1;
        end
