module clock_gate (
  input CLK,
  input EN,
  input TE,
  output reg ENCLK
);

  wire AND_out;
  reg D_flipflop_out;

  // First stage: AND gate
  assign AND_out = EN & TE;

  // Second stage: D flip-flop
  always @(posedge CLK) begin
    if (EN) begin
      D_flipflop_out <= AND_out;
    end
  end

  // Output
  always @* begin
    ENCLK = D_flipflop_out;
  end

