module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] shift_reg;
    reg [1:0] sel;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0000;
            sel <= 2'b00;
        end else if (load) begin
            shift_reg <= data;
            sel <= 2'b00;
        end else if (ena) begin
            sel <= sel + 1;
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end

    always @(*) begin
        case (sel)
            2'b00: q = shift_reg;
            2'b01: q = {shift_reg[3], shift_reg[2:0]};
            2'b10: q = {shift_reg[3:2], shift_reg[1:0]};
            2'b11: q = {shift_reg[3:1], shift_reg[0]};
        endcase
    end

