module priority_encoder (
    input [3:0] I,
    output reg [1:0] O
);

    always @(*) begin
        case (I)
            4'b0001: O = 2'b01;
            4'b0010: O = 2'b10;
            4'b0100: O = 2'b11;
            default: O = 2'b00;
        endcase
    end

endmodule
module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] D,
    output reg [3:0] Q
);

    always @(posedge clk) begin
        if (reset) begin
            Q <= 4'b0000;
        end else if (load) begin
            Q <= D;
        end else if (up_down) begin
            Q <= Q + 4'b0001;
        end else begin
            Q <= Q - 4'b0001;
        end
    end

