            tx_buffer <= tx_data;
            tx_busy_int <= 1;
            state <= TX_START;
          end
          else if (rx_complete) begin
            rx_data <= rx_buffer;
          end
        end
        TX_START: begin
          if (bit_counter == 0) begin
            rx_en_int <= 1;
          end
          else if (bit_counter == START_DELAY) begin
            rx_en_int <= 0;
            bit_counter <= 0;
            state <= TX_DATA;
          end
        end
        TX_DATA: begin
          if (bit_counter == 0) begin
            rx_en_int <= 1;
            tx_buffer <= {1'b0, tx_buffer[7:1]};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            rx_en_int <= 0;
            bit_counter <= 0;
            if (tx_buffer == 0) begin
              state <= RX_START;
            end
            else begin
              state <= TX_DATA;
            end
          end
        end
        RX_START: begin
          if (bit_counter == 0) begin
            rx_en_int <= 1;
          end
          else if (bit_counter == START_DELAY) begin
            rx_en_int <= 0;
            bit_counter <= 0;
            state <= RX_DATA;
          end
        end
        RX_DATA: begin
          if (bit_counter == 0) begin
            rx_buffer <= {rx_buffer[6:0], rx_en_int};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            rx_en_int <= 0;
            bit_counter <= 0;
