module top_module(
    input [7:0] in,
    input reset,
    input clk,
    output reg [3:0] q
);

    // AND operation
    wire [7:0] and_out;
    assign and_out = in & 8'b11100011;

    // 4-bit counter
    reg [3:0] count;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    // 4-bit adder
    wire [3:0] add_out;
    assign add_out = and_out + count;

    // Output
    always @(posedge clk) begin
        q <= add_out;
    end

