module ClockedNegativeOneShot(InputPulse, OneShot, Reset, CLOCK);

input InputPulse, Reset, CLOCK;
output reg OneShot;
parameter State0 = 0, State1 = 1, State2 = 2, State3 = 3;
reg [1:0] State;

always@(State)
    if(State == State1) OneShot <= 0;
    else OneShot <= 1;

always@(posedge CLOCK)
    if(Reset == 1) State <= State0;
    else
        case(State)
            State0: if(InputPulse == 1) State <= State1; else State <= State0;
            State1: if(InputPulse == 1) State <= State0; else State <= State3;
            State2: State <= State0;
            State3: if(InputPulse == 1) State <= State0; else State <= State3;
        endcase

endmodule,"After synthesis, this design has 1 a31oi_1, 1 and3_1, 2 clkinv_1, 3 dfxtp_1, 1 nor2_1, 2 nor3_1. ","Area of a31oi_1 is 6.26. Area of and3_1 is 6.26. Area of clkinv_1 is 3.75. Area of dfxtp_1 is 20.02. Area of nor2_1 is 3.75. Area of nor3_1 is 5.0.

