module xor4 (
    X,
    A,
    B,
    C,
    D
);

    // Port declaration
    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    // Internal signals
    wire AB, CD, ABCD;

    // Instantiate XOR gates
