module top_module (
    input [3:0] A, B, // Input for the magnitude comparator
    input [15:0] data_in, // Input for the binary ones counter
    input select, // Select input to choose between comparator and counter
    output [3:0] ones_count, // Output from the binary ones counter
    output [1:0] final_output // Final output based on the rules mentioned above
);

    wire EQ, GT, LT; // Output signals from the magnitude comparator

    // Instantiate the magnitude comparator module
    magnitude_comparator #(
        .N(4) // Specify the number of bits for the magnitude comparator
    ) comparator(
        .A(A),
        .B(B),
        .EQ(EQ),
        .GT(GT),
        .LT(LT)
    );

    wire [3:0] ones_count_raw; // Output from the binary ones counter

    // Instantiate the binary ones counter module
    binary_ones_counter #(
        .N(4) // Specify the number of bits for the binary ones counter
    ) counter(
        .data_in(data_in[3:0]), // Take only the first 4 bits of the input
        .ones_count_raw(ones_count_raw)
    );

    wire [3:0] ones_count_temp; // Temporary variable for the ones count output

    // Assign the ones count output based on the select input
    assign ones_count_temp = select ? ones_count_raw : 4'b0000; // Fixed the temporary assignment

    // Instantiate the control logic module
    control_logic #(
        .N(4) // Specify the number of bits for the control logic module
    ) control(
        .EQ(EQ),
        .GT(GT),
        .LT(LT),
        .ones_count_temp(ones_count_temp),
        .final_output(final_output)
    );

    // Assign the ones count output based on the select input
    assign ones_count = select ? ones_count_raw : 4'b0000;

endmodule
module magnitude_comparator #(
    parameter N = 4 // Number of bits for the magnitude comparator
) (
    input [N-1:0] A, B, // Input signals
    output EQ, GT, LT // Output signals
);

    wire [N-1:0] diff; // Difference between A and B

    assign diff = A - B;

    assign EQ = (diff == 0);
    assign GT = (diff > 0);
    assign LT = (diff < 0);

endmodule
module binary_ones_counter #(
    parameter N = 4 // Number of bits for the binary ones counter
) (
    input [N-1:0] data_in, // Input signal
    output [N-1:0] ones_count_raw // Output signal
);

    assign ones_count_raw = {N{1'b0}} + data_in;

endmodule
module control_logic #(
    parameter N = 4 // Number of bits for the control logic module
) (
    input EQ, GT, LT, // Input signals
    input [N-1:0] ones_count_temp, // Input signal from the binary ones counter
    output [1:0] final_output // Output signal based on the rules mentioned above
);

    assign final_output = EQ ? {1'b0, ones_count_temp[1:0]} :
                         GT ? {1'b1, ones_count_temp[2:1]} :
                         LT ? {1'b1, ones_count_temp[0]} : 2'b00;

endmodule,"After synthesis, this design has 3 and2_0, 1 clkinv_1, 2 mux2_1, 1 nand2_1, 1 nand4_1, 4 xnor2_1. ","Area of and2_0 is 6.26. Area of clkinv_1 is 3.75. Area of mux2_1 is 11.26. Area of nand2_1 is 3.75. Area of nand4_1 is 6.26. Area of xnor2_1 is 8.76.

