//739
module FSM_Convert_Float_To_Fixed(

    //INPUTS
    input wire CLK, //system clock
    input wire RST_FF, //system reset 
    input wire Exp_out, // INDICA SI EL VALOR DEL EXPONENTE ES MAYOR QUE 127 
    input wire Begin_FSM_FF, //inicia la maquina de estados 
    input wire [7:0] Exp, //CONTIENE EL EXPONENTE DEL NUMERO EN PUNTO FLOTANTE 
    // OUTPUTS		
    output reg EN_REG1, //ENABLE PARA EL REGISTRO QUE GUARDA EL NUMERO EN PUNTO FLOTANTE 
    output reg LOAD, //SELECCION PARA EL REGISTRO DE DESPLAZAMIENTOS 
    output reg MS_1, // SELECCION DEL MUX 1 (VALOR INICIAL DEL EXPONENTE , VALOR MODIFICADO DEL EXPONENTE)
    output reg ACK_FF, // INDICA QUE LA CONVERSION FUE REALIZADA
    output reg EN_MS_1,
    output reg EN_REG2,
    output reg RST
    );

parameter [3:0]  //se definen los estados que se utilizaran en la maquina
     a = 4'b0000,
     b = 4'b0001,
     c = 4'b0010,
     d = 4'b0011,
     e = 4'b0100,
     f = 4'b0101,
     g = 4'b0110,
     h = 4'b0111,
     i = 4'b1000;

reg [3:0] state_reg, state_next ; //state registers declaration

always @(posedge CLK, posedge RST_FF)

	if (RST_FF) begin
		state_reg <= a;	
	end

	else begin
		state_reg <= state_next;
	end

    always @*
    begin
        state_next = state_reg;    
        EN_REG1 = 1'b0;
        EN_REG2 = 1'b0;
        ACK_FF = 1'b0;
        EN_MS_1=1'b0;
        MS_1=1'b0;
        LOAD = 1'b0;
        RST = 1'b0;

        case(state_reg)
            a: 
            begin  
                if(Begin_FSM_FF) 
                    begin
                    RST = 1'b1;
                    ACK_FF = 1'b0;    
                    state_next = b;
                    end
                else
                    state_next = a;       
            end

            b: 
            begin
                EN_REG1 = 1'b1;    
                state_next = c;
            end

            c:
            begin
                EN_MS_1 = 1'b1;
                if(Exp_out) //if exponent greater than 127
                    MS_1 = 1'b1; //select modified exponent
                else
                    MS_1 = 1'b0; //select initial exponent
                if(Exp == 8'b01111111) //if exponent is all 1's
                    state_next = i; //go to state i
                else
                    state_next = d; //go to state d
            end

            d:
            begin
                EN_MS_1 = 1'b1;
                MS_1 = 1'b1; //select modified exponent
                state_next = e;
            end

            e:
            begin
                state_next = f;
            end 

            f:
            begin
                LOAD = 1'b1;
                state_next = g;
            end

            g:
            begin
                EN_REG2 = 1'b1;
                state_next = h;
            end

            h:
            begin
                ACK_FF = 1'b1;
                if(RST_FF)
                     state_next = a;
                else
                    state_next = h;
            end

            i:
            begin
                state_next = f;
            end

       default:
       state_next=a;
       endcase
    end

endmodule,"After synthesis, this design has 1 a31oi_1, 1 and3_1, 1 and4b_1, 5 clkinv_1, 4 dfrtp_1, 3 nand2_1, 1 nand3_1, 1 nand3b_1, 3 nand4_1, 2 nand4b_1, 5 nor2_1, 1 nor4_1, 2 nor4b_1, 2 nor4bb_1, 1 o21ai_0. ","Area of a31oi_1 is 6.26. Area of and3_1 is 6.26. Area of and4b_1 is 10.01. Area of clkinv_1 is 3.75. Area of dfrtp_1 is 25.02. Area of nand2_1 is 3.75. Area of nand3_1 is 5.0. Area of nand3b_1 is 7.51. Area of nand4_1 is 6.26. Area of nand4b_1 is 8.76. Area of nor2_1 is 3.75. Area of nor4_1 is 6.26. Area of nor4b_1 is 8.76. Area of nor4bb_1 is 10.01. Area of o21ai_0 is 5.0.

//740
module divider (
  input signed [n-1:0] dividend,
  input signed [n-1:0] divisor,
  output signed [n-1:0] quotient,
  output signed [n-1:0] remainder
);

parameter n = 16; // number of bits in dividend and divisor
parameter signed_div = 1; // set to 1 for signed division, 0 for unsigned division.

reg signed [n-1:0] dividend_reg;
reg signed [n-1:0] divisor_reg;
reg signed [n-1:0] quotient_reg;
reg signed [n-1:0] remainder_reg;

always @(*) begin
  dividend_reg = dividend;
  divisor_reg = divisor;

  if (divisor == 0) begin
    quotient_reg = 0;
    remainder_reg = 0;
  end
  else if (signed_div == 1) begin // signed division
    if (dividend < 0) begin
      if (divisor < 0) begin
        dividend_reg = -dividend;
        divisor_reg = -divisor;
      end
      quotient_reg = -dividend_reg / divisor_reg;
    end
    else begin
      if (divisor < 0) begin
        divisor_reg = -divisor;
        quotient_reg = -dividend_reg / divisor_reg;
      end
      else begin
        quotient_reg = dividend_reg / divisor_reg;
      end
    end
    remainder_reg = dividend_reg - quotient_reg * divisor_reg;
  end
  else begin // unsigned division
    quotient_reg = dividend_reg / divisor_reg;
    remainder_reg = dividend_reg % divisor_reg;
  end
end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule,"After synthesis, this design has 1 a2111o_1, 1 a2111oi_0, 4 a211o_1, 15 a211oi_1, 1 a21bo_1, 12 a21boi_0, 10 a21o_1, 103 a21oi_1, 1 a221o_1, 1 a221oi_1, 5 a22oi_1, 1 a2bb2oi_1, 1 a311o_1, 5 a311oi_1, 1 a31o_1, 12 a31oi_1, 1 a32oi_1, 3 a41oi_1, 42 and2_0, 5 and3_1, 3 and4_1, 71 clkinv_1, 106 maj3_1, 12 mux2_1, 22 mux2i_1, 158 nand2_1, 30 nand2b_1, 15 nand3_1, 1 nand3b_1, 7 nand4_1, 1 nand4b_1, 295 nor2_1, 18 nor2b_1, 24 nor3_1, 2 nor3b_1, 10 nor4_1, 1 nor4b_1, 3 o211a_1, 39 o211ai_1, 20 o21a_1, 129 o21ai_0, 2 o21bai_1, 3 o221ai_1, 3 o22a_1, 9 o22ai_1, 3 o311a_1, 2 o311ai_0, 4 o31a_1, 16 o31ai_1, 1 o41a_1, 16 or2_0, 9 or3_1, 9 or4_1, 1 or4b_1, 291 xnor2_1, 24 xnor3_1, 92 xor2_1, 12 xor3_1. ","Area of a2111o_1 is 11.26. Area of a2111oi_0 is 8.76. Area of a211o_1 is 8.76. Area of a211oi_1 is 7.51. Area of a21bo_1 is 10.01. Area of a21boi_0 is 7.51. Area of a21o_1 is 7.51. Area of a21oi_1 is 5.0. Area of a221o_1 is 10.01. Area of a221oi_1 is 8.76. Area of a22oi_1 is 7.51. Area of a2bb2oi_1 is 8.76. Area of a311o_1 is 10.01. Area of a311oi_1 is 8.76. Area of a31o_1 is 8.76. Area of a31oi_1 is 6.26. Area of a32oi_1 is 8.76. Area of a41oi_1 is 8.76. Area of and2_0 is 6.26. Area of and3_1 is 6.26. Area of and4_1 is 8.76. Area of clkinv_1 is 3.75. Area of maj3_1 is 10.01. Area of mux2_1 is 11.26. Area of mux2i_1 is 10.01. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nand3_1 is 5.0. Area of nand3b_1 is 7.51. Area of nand4_1 is 6.26. Area of nand4b_1 is 8.76. Area of nor2_1 is 3.75. Area of nor2b_1 is 6.26. Area of nor3_1 is 5.0. Area of nor3b_1 is 7.51. Area of nor4_1 is 6.26. Area of nor4b_1 is 8.76. Area of o211a_1 is 10.01. Area of o211ai_1 is 7.51. Area of o21a_1 is 7.51. Area of o21ai_0 is 5.0. Area of o21bai_1 is 7.51. Area of o221ai_1 is 8.76. Area of o22a_1 is 8.76. Area of o22ai_1 is 6.26. Area of o311a_1 is 10.01. Area of o311ai_0 is 8.76. Area of o31a_1 is 8.76. Area of o31ai_1 is 7.51. Area of o41a_1 is 11.26. Area of or2_0 is 6.26. Area of