      else if(data_prev) begin
        m_axis_rx_tvalid <= #TCQ (trn_rsrc_rdy_prev || dsc_flag);
        reg_tlast        <= #TCQ trn_reof_prev;
        reg_tkeep        <= #TCQ tkeep_prev;
        m_axis_rx_tuser  <= #TCQ {is_eof_prev,          2'b00,                is_sof_prev,          1'b0,                 trn_rbar_hit_prev,    trn_rerrfwd_prev,     trn_recrc_err_prev};  end

      else begin
        m_axis_rx_tvalid <= #TCQ (rsrc_rdy_filtered || dsc_flag);
        reg_tlast        <= #TCQ trn_reof;
        reg_tkeep        <= #TCQ tkeep;
        m_axis_rx_tuser  <= #TCQ {is_eof,               2'b00,                is_sof,               1'b0,                 trn_rbar_hit,         trn_rerrfwd,          trn_recrc_err};       end
    end
    end
end

generate
  if(C_DATA_WIDTH == 128) begin : tlast_tkeep_hookup_128
    assign m_axis_rx_tlast = 1'b0;
    assign m_axis_rx_tkeep = {KEEP_WIDTH{1'b1}};
  end

  else begin : tlast_tkeep_hookup_64_32
    assign m_axis_rx_tlast = reg_tlast;
    assign m_axis_rx_tkeep = reg_tkeep;
  end
endgenerate


generate
  if(C_DATA_WIDTH == 128) begin : rrem_to_tkeep_128
    assign tkeep      = 16'h0000;
    assign tkeep_prev = 16'h0000;
  end
  else if(C_DATA_WIDTH == 64) begin : rrem_to_tkeep_64
    assign tkeep      = trn_rrem      ? 8'hFF : 8'h0F;
    assign tkeep_prev = trn_rrem_prev ? 8'hFF : 8'h0F;
  end
  else begin : rrem_to_tkeep_32
    assign tkeep      = 4'hF;
    assign tkeep_prev = 4'hF;
  end
endgenerate


generate
  if(C_DATA_WIDTH == 128) begin : is_sof_128
    assign is_sof      = {(trn_rsof && !trn_rsrc_dsc), (trn_rsof && !trn_rrem[1]),  3'b000};                     assign is_sof_prev = {(trn_rsof_prev && !trn_rsrc_dsc_prev), (trn_rsof_prev && !trn_rrem_prev[1]),  3'b000};                               end
  else begin : is_sof_64_32
    assign is_sof      = {(trn_rsof && !trn_rsrc_dsc), 4'b0000};                    assign is_sof_prev = {(trn_rsof_prev && !trn_rsrc_dsc_prev), 4'b0000};                              end
endgenerate


generate
  if(C_DATA_WIDTH == 128) begin : is_eof_128
    assign is_eof      = {trn_reof,      trn_rrem,      2'b11};        assign is_eof_prev = {trn_reof_prev, trn_rrem_prev, 2'b11};        end
  else if(C_DATA_WIDTH == 64) begin : is_eof_64
    assign is_eof      = {trn_reof,      1'b0,          trn_rrem,      2'b11};        assign is_eof_prev = {trn_reof_prev, 1'b0,          trn_rrem_prev, 2'b11};        end
  else begin : is_eof_32
    assign is_eof      = {trn_reof,      4'b0011};      assign is_eof_prev = {trn_reof_prev, 4'b0011};      end
endgenerate



always @(posedge user_clk) begin
  if(user_rst) begin
    trn_rdst_rdy <= #TCQ 1'b0;
  end
  else begin
    if(null_mux_sel && m_axis_rx_tready) begin
      trn_rdst_rdy <= #TCQ null_rdst_rdy;
    end

    else if(dsc_flag) begin
      trn_rdst_rdy <= #TCQ 1'b0;
    end

    else if(m_axis_rx_tvalid) begin
      trn_rdst_rdy <= #TCQ m_axis_rx_tready;
    end

    else begin
      trn_rdst_rdy <= #TCQ 1'b1;
    end
  end
end

always @(posedge user_clk) begin
  if(user_rst) begin
    null_mux_sel <= #TCQ 1'b0;
  end
  else begin
    if(null_mux_sel && null_rx_tlast && m_axis_rx_tready)
    begin
      null_mux_sel <= #TCQ 1'b0;
    end

    else if(dsc_flag && !data_hold) begin
      null_mux_sel <= #TCQ 1'b1;
    end
  end
end


always @(posedge user_clk) begin
  if(user_rst) begin
    trn_in_packet <= #TCQ 1'b0;
  end
  else begin
    if(trn_rsof && !trn_reof && rsrc_rdy_filtered && trn_rdst_rdy)
    begin
      trn_in_packet <= #TCQ 1'b1;
    end
    else if(trn_rsrc_dsc) begin
      trn_in_packet <= #TCQ 1'b0;
    end
    else if(trn_reof && !trn_rsof && trn_rsrc_rdy && trn_rdst_rdy) begin
      trn_in_packet <= #TCQ 1'b0;
    end
  end
end


assign dsc_detect = trn_rsrc_dsc && !trn_rsrc_dsc_d && trn_in_packet &&
                         (!trn_rsof || trn_reof) && !(trn_rdst_rdy && trn_reof);

always @(posedge user_clk) begin
  if(user_rst) begin
    reg_dsc_detect <= #TCQ 1'b0;
    trn_rsrc_dsc_d <= #TCQ 1'b0;
  end
  else begin
    if(dsc_detect) begin
      reg_dsc_detect <= #TCQ 1'b1;
    end
    else if(null_mux_sel) begin
      reg_dsc_detect <= #TCQ 1'b0;
    end

    trn_rsrc_dsc_d <= #TCQ trn_rsrc_dsc;
  end
end

assign dsc_flag = dsc_detect || reg_dsc_detect;



generate
  if(C_FAMILY == "V6" && C_DATA_WIDTH == 128) begin : np_cntr_to_128_enabled
    reg [2:0] reg_np_counter;

    wire mrd_lower      = (!(|m_axis_rx_tdata[92:88]) && !m_axis_rx_tdata[94]);
    wire mrd_lk_lower   = (m_axis_rx_tdata[92:88] == 5'b00001);
    wire io_rdwr_lower  = (m_axis_rx_tdata[92:88] == 5'b00010);
    wire cfg_rdwr_lower = (m_axis_rx_tdata[92:89] == 4'b0010);
    wire atomic_lower   = ((&m_axis_rx_tdata[91:90]) && m_axis_rx_tdata[94]);

    wire np_pkt_lower = (mrd_lower      ||
                         mrd_lk_lower   ||
                         io_rdwr_lower  ||
                         cfg_rdwr_lower ||
                         atomic_lower) && m_axis_rx_tuser[13];

    wire mrd_upper      = (!(|m_axis_rx_tdata[28:24]) && !m_axis_rx_tdata[30]);
    wire mrd_lk_upper   = (m_axis_rx_tdata[28:24] == 5'b00001);
    wire io_rdwr_upper  = (m_axis_rx_tdata[28:24] == 5'b00010);
    wire cfg_rdwr_upper = (m_axis_rx_tdata[28:25] == 4'b0010);
    wire atomic_upper   = ((&m_axis_rx_tdata[27:26]) && m_axis_rx_tdata[30]);

    wire np_pkt_upper = (mrd_upper      ||
                         mrd_lk_upper   ||
                         io_rdwr_upper  ||
                         cfg_rdwr_upper ||
                         atomic_upper) && !m_axis_rx_tuser[13];

    wire pkt_accepted =
                    m_axis_rx_tuser[14] && m_axis_rx_tready && m_axis_rx_tvalid;

    always @(posedge user_clk)  begin
      if (user_rst) begin
        reg_np_counter <= #TCQ 0;
      end
      else begin
        if((np_pkt_lower || np_pkt_upper) && pkt_accepted)
        begin
          reg_np_counter <= #TCQ reg_np_counter + 3'h1;
        end
      end
    end

    assign np_counter = reg_np_counter;
  end
  else begin : np_cntr_to_128_disabled
    assign np_counter = 3'h0;
  end
endgenerate


endmodule
,"After synthesis, this design has 130 a211oi_1, 134 a21oi_1, 2 a22o_1, 1 a31o_1, 3 a31oi_1, 1 a41oi_1, 3 clkinv_1, 2 conb_1, 294 dfxtp_1, 152 mux2i_1, 145 nand2_1, 5 nand2b_1, 4 nand3_1, 1 nand3b_1, 1 nand4_1, 278 nor2_1, 4 nor2b_1, 3 nor3_1, 1 o2111ai_1, 4 o211ai_1, 1 o21a_1, 10 o21ai_0, 2 or2_0, 1 or3_1, 1 or3b_1. ","Area of a211oi_1 is 7.51. Area of a21oi_1 is 5.0. Area of a22o_1 is 8.76. Area of a31o_1 is 8.76. Area of a31oi_1 is 6.26. Area of a41oi_1 is 8.76. Area of clkinv_1 is 3.75. Area of conb_1 is 3.75. Area of dfxtp_1 is 20.02. Area of mux2i_1 is 10.01. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nand3_1 is 5.0. Area of nand3b_1 is 7.51. Area of nand4_1 is 6.26. Area of nor2_1 is 3.75. Area of nor2b_1 is 6.26. Area of nor3_1 is 5.0. Area of o2111ai_1 is 8.76. Area of o211ai_1 is 7.51. Area of o21a_1 is 7.51. Area of o21ai_0 is 5.0. Area of or2_0 is 6.26. Area of or3_1 is 6.26. Area of or3b_1 is 8.76.

//742
module mux_adder (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] a, // 4-bit input A
    input [3:0] b, // 4-bit input B
    input sel, // Select input to choose between addition and multiplexer
    output [3:0] q // 4-bit output from the module
);

    // Create a 2:1 multiplexer with two additional inputs set to 0 and 1
    wire [3:0] mux_out;
    wire inv_mux_out;
    assign mux_out = sel ? {4{1'b0}} : a;
    assign inv_mux_out = (b >= mux_out) ? ~mux_out : mux_out;

    // Create an adder with carry-in and carry-out ports
    wire [3:0] add_out;
    wire carry_out;
    assign {carry_out, add_out} = a + b;

    // Choose between the output of the adder and the multiplexer
    assign q = sel ? inv_mux_out : add_out;

endmodule,"After synthesis, this design has 1 a21oi_1, 1 and2_0, 2 maj3_1, 3 nor2_1, 2 o21bai_1, 2 xnor2_1, 3 xor2_1. ","Area of a21oi_1 is 5.0. Area of and2_0 is 6.26. Area of maj3_1 is 10.01. Area of nor2_1 is 3.75. Area of o21bai_1 is 7.51. Area of xnor2_1 is 8.76. Area of xor2_1 is 8.76.

//743
module acl_fp_convert_from_long(clock, resetn, dataa, result, enable, valid_in, valid_out, stall_in, stall_out);
	parameter UNSIGNED = 0;
	parameter HIGH_CAPACITY = 1;
	parameter ROUNDING_MODE = 0;	
    input clock, resetn;
	input [63:0] dataa;
	output [31:0] result;
	input enable, valid_in, stall_in;
	output valid_out, stall_out;

	reg c1_valid;
	wire c1_stall;
	wire c1_enable;
	reg c2_valid;
	wire c2_stall;
	wire c2_enable;
	reg c3_valid;
	wire c3_stall;
	wire c3_enable;
	reg c4_valid;
	wire c4_stall;
	wire c4_enable;
	reg c5_valid;
	wire c5_stall;
	wire c5_enable;	

	reg [63:0] c1_value_to_convert;
	reg c1_sign;
	assign c1_enable = (HIGH_CAPACITY == 1) ? (~c1_valid | ~c1_stall) : enable;
	assign stall_out = c1_valid & c1_stall;

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
			c1_valid <= 1'b0;
			c1_sign <= 1'bx;
			c1_value_to_convert <= 64'dx;
		end
		else if (c1_enable)
		begin
			c1_valid <= valid_in;

			if (UNSIGNED == 1)
			begin
				c1_sign <= 1'b0;
				c1_value_to_convert <= dataa;
			end
			else
			begin
				c1_sign <= dataa[63];
				c1_value_to_convert <= (dataa ^ {64{dataa[63]}}) + {1'b0, dataa[63]};
			end
		end
	end

	reg [63:0] c2_value_to_convert;
	reg [7:0] c2_exponent;
	reg c2_sign, c2_done;
	assign c2_enable = (HIGH_CAPACITY == 1) ? (~c2_valid | ~c2_stall) : enable;
	assign c1_stall = c2_valid & c2_stall;	

	wire top_bits_0 = ~(|c1_value_to_convert[63:32]);
	wire top_bits_half_0 = ~(|c1_value_to_convert[63:48]);
	wire bottom_bits_0 = ~(|c1_value_to_convert[31:0]);
	wire bottom_bits_half_0 = ~(|c1_value_to_convert[31:16]);

	reg [1:0] c2_shift_value;
	always@(*)
	begin
		c2_shift_value[1] = top_bits_0;
		c2_shift_value[0] = top_bits_0 & bottom_bits_half_0 | ~top_bits_0 & top_bits_half_0;
	end

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
			c2_valid <= 1'b0;
			c2_value_to_convert <= 64'dx;
			c2_exponent <= 8'dx;
			c2_sign <= 1'bx;
			c2_done <= 1'bx;
		end
		else if (c2_enable)
		begin
			c2_valid <= c1_valid;
			c2_sign <= c1_sign;
   		c2_done <= top_bits_0 & bottom_bits_0;			
			if (top_bits_0 & bottom_bits_0)
			begin
				c2_exponent <= 8'd0;
				c2_value_to_convert <= c1_value_to_convert;
			end
			else 
			begin
				c2_exponent <= 8'd190 - {1'b0, c2_shift_value, 4'd0}; case(c2_shift_value)
				  2'b11: c2_value_to_convert <= {c1_value_to_convert[15:0], 48'd0};
				  2'b10: c2_value_to_convert <= {c1_value_to_convert[31:0], 32'd0};
				  2'b01: c2_value_to_convert <= {c1_value_to_convert[47:0], 16'd0};
				  2'b00: c2_value_to_convert <= c1_value_to_convert;
				endcase
			end
		end
	end

	reg [63:0] c3_value_to_convert;
	reg [7:0] c3_exponent;
	reg c3_sign, c3_done;
	assign c3_enable = (HIGH_CAPACITY == 1) ? (~c3_valid | ~c3_stall) : enable;
	assign c2_stall = c3_valid & c3_stall;	

	wire top_12bits_0 = ~(|c2_value_to_convert[63:52]);
	wire top_8bits_0 = ~(|c2_value_to_convert[63:56]);
	wire top_4bits_0 = ~(|c2_value_to_convert[63:60]);

	reg [1:0] c3_exp_adjust;
	always@(*)
	begin
		if (top_12bits_0 & ~c2_done)
			c3_exp_adjust = 2'd3;
		else if (top_8bits_0 & ~c2_done)
			c3_exp_adjust = 2'd2;
		else if (top_4bits_0 & ~c2_done)
			c3_exp_adjust = 2'd1;
		else
			c3_exp_adjust = 2'd0;
	end

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
			c3_valid <= 1'b0;
			c3_value_to_convert <= 64'dx;
			c3_exponent <= 8'dx;
			c3_sign <= 1'bx;
			c3_done <= 1'bx;
		end
		else if (c3_enable)
		begin
			c3_valid <= c2_valid;
			c3_sign <= c2_sign;
			c3_done <= c2_done;
			c3_exponent <= c2_exponent - {1'b0, c3_exp_adjust, 2'd0};
			case (c3_exp_adjust)
				2'b11: c3_value_to_convert <= {c2_value_to_convert[51:0], 12'd0};
				2'b10: c3_value_to_convert <= {c2_value_to_convert[55:0], 8'd0};
				2'b01: c3_value_to_convert <= {c2_value_to_convert[59:0], 4'd0};
				2'b00: c3_value_to_convert <= c2_value_to_convert;
			endcase
		end
	end	

	reg [63:0] c4_value_to_convert;
	reg [7:0] c4_exponent;
	reg c4_sign;
	assign c4_enable = (HIGH_CAPACITY == 1) ? (~c4_valid | ~c4_stall) : enable;
	assign c3_stall = c4_valid & c4_stall;	

	wire top_3bits_0 = ~(|c3_value_to_convert[63:61]);
	wire top_2bits_0 = ~(|c3_value_to_convert[63:62]);
	wire top_1bits_0 = ~(c3_value_to_convert[63]);

	reg [1:0] c4_exp_adjust;
	always@(*)
	begin
		if (top_3bits_0 & ~c3_done)
			c4_exp_adjust = 2'd3;
		else if (top_2bits_0 & ~c3_done)
			c4_exp_adjust = 2'd2;
		else if (top_1bits_0 & ~c3_done)
			c4_exp_adjust = 2'd1;
		else
			c4_exp_adjust = 2'd0;
	end

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
			c4_valid <= 1'b0;
			c4_value_to_convert <= 64'dx;
			c4_exponent <= 8'dx;
			c4_sign <= 1'bx;
		end
		else if (c4_enable)
		begin
			c4_valid <= c3_valid;
			c4_sign <= c3_sign;
			c4_exponent <= c3_exponent - {1'b0, c4_exp_adjust};
			case (c4_exp_adjust)
				2'b11: c4_value_to_convert <= {c3_value_to_convert[60:0], 3'd0};
				2'b10: c4_value_to_convert <= {c3_value_to_convert[61:0], 2'd0};
				2'b01: c4_value_to_convert <= {c3_value_to_convert[62:0], 1'd0};
				2'b00: c4_value_to_convert <= c3_value_to_convert;
			endcase
		end
	end	

	reg [22:0] c5_mantissa;
	reg [7:0] c5_exponent;
	reg c5_sign;

	assign c5_enable = (HIGH_CAPACITY == 1) ? (~c5_valid | ~c5_stall) : enable;
	assign c4_stall = c5_valid & c5_stall;	
	wire [3:0] c5_bottom_4 = {c4_value_to_convert[40:38], |c4_value_to_convert[37:0]};
	reg [24:0] c5_temp_mantissa;
    always@(*)
	begin
		case (ROUNDING_MODE)
			4: begin
				if (UNSIGNED == 1)
				begin
					c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
				end
				else
				begin		
					if (|c5_bottom_4[2:0] & c4_sign)
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]} + 1'b1;
					else
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
				end
			end

			3: begin
				if (UNSIGNED == 1)
				begin
					if (|c5_bottom_4[2:0])
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]} + 1'b1;
					else
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
				end
				else
				begin		
					if (|c5_bottom_4[2:0] & ~c4_sign)
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]} + 1'b1;
					else
						c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
				end
			end

   		2: begin
				c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
			end

			1: begin
				if (c5_bottom_4[2])
					c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]} + 1'b1;
				else
					c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
			end

  		   default: begin
				if ((&c5_bottom_4[3:2]) || (c5_bottom_4[2] & |c5_bottom_4[1:0]))
					c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]} + 1'b1;
				else
					c5_temp_mantissa <= {1'b0, c4_value_to_convert[63:40]};
			end
		endcase	
	end

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
			c5_valid <= 1'b0;
			c5_mantissa <= 32'dx;
			c5_exponent <= 8'dx;
			c5_sign <= 1'bx;
		end
		else if (c5_enable)
		begin
			c5_valid <= c4_valid;
			c5_sign <= c4_sign;
			c5_exponent <= c4_exponent + c5_temp_mantissa[24];
			c5_mantissa <= c5_temp_mantissa[24] ? c5_temp_mantissa[23:1] :  c5_temp_mantissa[22:0];
		end
	end	

	assign c5_stall = stall_in;
	assign result = {c5_sign, c5_exponent, c5_mantissa};
