//753
module top_module ( 
    input [2:0] sel, // Select input for the 6-to-1 multiplexer
    input [3:0] data0, // Data inputs for the 6-to-1 multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [7:0] in, // 8-bit input for the bit-reversal module
    output [7:0] out // 8-bit output
);

// 6-to-1 Multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 0) ? data0 :
                 (sel == 1) ? data1 :
                 (sel == 2) ? data2 :
                 (sel == 3) ? data3 :
                 (sel == 4) ? data4 :
                              data5;

// Bit-reversal module
wire [7:0] rev_out;
bit_reversal_module br_module (
    .in(in),
    .out(rev_out)
);

// Bitwise OR module
wire [7:0] or_out;
assign or_out = mux_out | rev_out;

// Output
assign out = or_out;

endmodule

module bit_reversal_module (
    input [7:0] in,
    output [7:0] out
);

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : bit_reverse
        assign out[i] = in[7-i];
    end
endgenerate

