				end
			8:	begin			
					case(sel)
						3'b000 : data[C_SIZE-1:0] <= a[C_SIZE-1:0] ;
						3'b001 : data[C_SIZE-1:0] <= b[C_SIZE-1:0] ;
						3'b010 : data[C_SIZE-1:0] <= c[C_SIZE-1:0] ;
						3'b011 : data[C_SIZE-1:0] <= d[C_SIZE-1:0] ;
