module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] adder_out;
wire carry_out;

carry_lookahead_adder adder_inst (
    .a(a),
    .b(b),
    .s(adder_out),
    .carry_out(carry_out)
);

bitwise_XOR xor_inst (
    .a(adder_out),
    .b(b),
    .s(s)
);

assign overflow = ((a[7] == b[7]) && (s[7] != a[7])) ? 1'b1 : 1'b0;

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

wire [7:0] p, g, c;

assign p = a ^ b;
assign g = a & b;
assign c[0] = g[0];

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen
        assign c[i] = g[i] | (p[i] & c[i-1]);
    end
endgenerate

assign s = p ^ c;
assign carry_out = c[7];

endmodule

module bitwise_XOR (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s
);

assign s = a ^ b;

