begin
	if (reset) begin
		A <= 0;
		C <= 0;
		B <= 0;
		Q <= 0;
		P <= m_size;
	end else begin
		if (Load_regs) begin
			A = 0;
			C = 0;
			B = multiplicand;
			Q = multiplier;
			P = m_size;
		end else begin
			if (Add_regs) {C, A} = A + B;
			if (Shift_regs) {C, A, Q} = {C, A, Q} >> 1;
