parameter VGA_MAX_V      = 525;
parameter VGA_WIDTH      = 640;
parameter VGA_HEIGHT     = 480;
parameter VGA_SYNH_START = 656;
parameter VGA_SYNV_START = 490;
parameter VGA_SYNH_END   = 752;
parameter VGA_SYNV_END   = 492;

