module rising_edge_detector (
    input clk,
    input [31:0] in32,
    input reset,
    output reg [31:0] out
);
    reg [31:0] prev_in;
    reg [31:0] rising_edge_mask;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prev_in <= 32'b0;
            rising_edge_mask <= 32'b0;
            out <= 32'b0;
        end else begin
            prev_in <= in32;
            rising_edge_mask <= (in32 ^ prev_in) & in32;
            out <= out | rising_edge_mask;
        end
    end
endmodule
module bitwise_or (
    input [31:0] in1,
    input [31:0] in2,
    output [31:0] out
);
    assign out = in1 | in2;
endmodule
