    input reset,
    input [7:0] in,
    input [31:0] in32,
    output reg [31:0] out
);
    wire [7:0] reversed_in;
    wire [31:0] rising_edge_out;

    barrel_shifter bs (
        .in(in),
        .out(reversed_in)
    );

    rising_edge_detector red (
        .clk(clk),
        .in32(in32),
        .reset(reset),
        .out(rising_edge_out)
    );

    bitwise_or bo (
        .in1({24'b0, reversed_in}),
        .in2(rising_edge_out),
        .out(out)
    );
