reg APrevious;
reg ACurrent;
reg BCurrent;
reg[31:0] Count;
reg[31:0] CountOutput;
reg Dir;
reg DirectionOutput;

always @(posedge clock) begin

	if (reset_l == 1'b0)
	begin
		Count[31:0] <= 32'h80000000;	
