				Dir <= 1'b1;
			end
			else begin
				Count <= Count - 1'b1;
				Dir <= 1'b0;
			end
		end
	end
end

always @(negedge clock) begin
		APrevious <= A;		
		BPrevious <= B;
		CountOutput <= Count;
		DirectionOutput <= Dir;
end

assign CurrentCount = CountOutput;
assign Direction = DirectionOutput;

endmodule
