module binary_edge_detector (
    input clk,
    input rst_n,
    input bin_in,
    output reg rise_edge,
    output reg fall_edge
);

reg prev_bin_in;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        prev_bin_in <= 1'b0;
    end else begin
        rise_edge <= (bin_in && !prev_bin_in);
        fall_edge <= (!bin_in && prev_bin_in);
        prev_bin_in <= bin_in;
    end
end

endmodule

