module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [2:0] select, // Select input to choose between multiplexer and rising edge detector
    input [31:0] in, // 32-bit input for the rising edge detector
    output [31:0] out, // 32-bit output from the active module
    output [3:0] wxyz // Output ports for the multiplexer
);

    // Define internal signals
    reg [1:0] select_internal;
    reg [31:0] out_internal;
    wire [3:0] wxyz_internal;
    wire [31:0] in_internal;
    wire [31:0] in_delayed;
    wire [31:0] rising_edge_internal;
    reg [31:0] out_mux;
    reg [31:0] out_red;

    // Instantiate the multiplexer
    mux_3to4 mux_inst (
        .a(in_internal),
        .b(in_delayed),
        .c(rising_edge_internal),
        .s(select_internal),
        .w(wxyz_internal)
    );

    // Instantiate the rising edge detector
    red_32bit red_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(rising_edge_internal)
    );

    // Define control logic for selecting between modules
    always @ (posedge clk) begin
        if (reset) begin
            select_internal <= 0;
        end else begin
            select_internal <= select;
        end
    end

    // Define output logic for the multiplexer
    always @ (*) begin
        case (wxyz_internal)
            4'b0001: out_mux <= in_internal;
            4'b0010: out_mux <= in_delayed;
            4'b0100: out_mux <= rising_edge_internal;
            default: out_mux <= 0;
        endcase
    end

    // Define output logic for the rising edge detector
    always @ (posedge clk) begin
        if (reset) begin
            out_red <= 0;
        end else begin
            out_red <= rising_edge_internal;
        end
    end

    // Define output logic for the active module
    always @ (*) begin
        if (reset) begin
            out_internal <= 0;
        end else begin
            if (select_internal == 3'b000) begin
                out_internal <= out_mux;
            end else begin
                out_internal <= out_red;
            end
        end
    end

    // Connect internal signals to module ports
    assign wxyz = wxyz_internal;
    assign out = out_internal;
    assign in_internal = in;
    assign in_delayed = {in[30:0], 1'b0};

endmodule

module mux_3to4 (
    input [31:0] a,
    input [31:0] b,
    input [31:0] c,
    input [1:0] s,
    output [3:0] w
);
    assign w[0] = a[0] & ~s[1] & ~s[0] | b[0] & ~s[1] & s[0] | c[0] & s[1] & ~s[0];
    assign w[1] = a[1] & ~s[1] & ~s[0] | b[1] & ~s[1] & s[0] | c[1] & s[1] & ~s[0];
    assign w[2] = a[2] & ~s[1] & ~s[0] | b[2] & ~s[1] & s[0] | c[2] & s[1] & ~s[0];
    assign w[3] = a[3] & ~s[1] & ~s[0] | b[3] & ~s[1] & s[0] | c[3] & s[1] & ~s[0];
endmodule

module red_32bit (
    input clk,
    input reset, // Synchronous active-high reset
    input [31:0] in,
    output [31:0] out
);
    reg [31:0] in_delayed;

    always @ (posedge clk) begin
        if (reset) begin
            in_delayed <= 0;
        end else begin
            in_delayed <= in;
        end
    end

    assign out = in & ~in_delayed;
endmodule
