		next_ready = 0;
		next_exponent = 0;
		next_temp_product = 1;
	 end

	 always @(posedge clk) begin
		ready <= next_ready;
		exponent <= next_exponent;
		temp_product <= next_temp_product;
	 end

	 always @(*) begin

			if (input_enable) begin
				if (temp_product < boundary) begin
					next_temp_product = temp_product * base;
					next_ready = 0;
					next_exponent = exponent + 1;
				end else begin
					next_temp_product = temp_product;
					next_ready = 1;
					next_exponent = exponent;
				end
			end else begin
				if (ready) begin
					next_ready = 1;
					next_exponent = exponent;
					next_temp_product = 1;
				end else begin
					next_temp_product = 1;
					next_ready = 0;
					next_exponent = 0;
				end

			end
	 end


