module uart_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  input start_bit,
  input stop_bit,
  output tx
);

parameter baud_rate = 9600;
reg [15:0] baud_counter;
reg [9:0] shift_reg;
reg tx_state;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    baud_counter <= 0;
    shift_reg <= 0;
    tx_state <= 1'b1;
  end else begin
    if (baud_counter == (50_000_000 / baud_rate) - 1) begin
      baud_counter <= 0;
      if (start_bit) begin
        shift_reg <= {stop_bit, data_in, 1'b0};
        tx_state <= 1'b0;
      end else if (!tx_state) begin
        shift_reg <= shift_reg >> 1;
        if (shift_reg == 1) begin
          tx_state <= 1'b1;
        end
      end
    end else begin
      baud_counter <= baud_counter + 1;
    end
  end
end

assign tx = tx_state;

endmodule

