                     (select == 3) ? data3 :
                     (select == 4) ? data4 :
                     (select == 5) ? data5 :
                     4'b00;

    // Bitwise AND of two least significant bits
    wire [1:0] and_out;
    assign and_out = data0[1:0] & data1[1:0] & data2[1:0] & data3[1:0] & data4[1:0] & data5[1:0];

