module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input M,
  output [3:0] S
);

  // Local signals
  wire [3:0] sum;
  wire [4:0] carry;

  // Generate the sum and carry using a full adder
  assign carry[0] = 1'b0;
  genvar i;
  generate
    for(i = 0; i < 4; i = i + 1) begin : full_adder
      full_adder fa(
        .A(A[i]),
        .B(B[i]),
        .Cin(carry[i]),
        .S(sum[i]),
        .Cout(carry[i + 1])
      );
    end
  endgenerate

  // Perform unsigned or two's complement addition based on the mode input
  assign S = (M == 0) ? sum : sum + (~M + 1);

endmodule
module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign {Cout, S} = A + B + Cin;

