module four_bit_adder(
    A,
    B,
    Cin,
    Clk,
    S,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    input Clk;
    output [3:0] S;
    output Cout;

    reg [3:0] sum;
    reg carry;
    wire [3:0] sum_wire;
    wire Cout_wire;

    // Full Adder
    assign sum_wire = A + B + Cin;
    assign Cout_wire = (A[3] & B[3]) | (Cin & (A[3] ^ B[3]));

    always @(posedge Clk) begin
        sum <= sum_wire;
        carry <= Cout_wire;
    end

    assign S = sum;
    assign Cout = carry;

endmodule
