module shift_register (
    input clk,
    input reset, // Active-high asynchronous reset
    input [7:0] data_in, // 8-bit input for the shift register
    input [1:0] shift_direction, // Control input for shifting direction
    input load, // Load input for parallel load
    output [7:0] q // 8-bit output from the shift register
);

reg [7:0] shift_reg = 8'h34; // Initial value of shift register

always @(posedge clk or posedge reset) begin
    if (reset) begin
        shift_reg <= 8'h34;
    end else begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            case (shift_direction)
                2'b00: shift_reg <= {shift_reg[6:0], shift_reg[7]};
                2'b01: shift_reg <= {shift_reg[0], shift_reg[7:1]};
                2'b10: shift_reg <= shift_reg;
                2'b11: shift_reg <= {shift_reg[0], shift_reg[7:1]};
            endcase
        end
    end
end

assign q = shift_reg;

endmodule
module counter (
    input clk,
    input reset, // Synchronous reset
    output reg [3:0] count // 4-bit binary up counter
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule
module control_logic (
    input select, // Select input to choose between shift register and counter
    input [7:0] shift_reg_out, // Output from the shift register
    input [3:0] count_out, // Output from the counter
    output [7:0] active_out // Output from the active module
);

assign active_out = select ? count_out : shift_reg_out;

endmodule
module top_module (
    input clk,
    input reset, // Active-high asynchronous reset
    input [7:0] data_in, // 8-bit input for the shift register
    input [1:0] shift_direction, // Control input for shifting direction
    input load, // Load input for parallel load
    input select, // Select input to choose between shift register and counter
    output [7:0] q // 8-bit output from the active module
);

wire [7:0] shift_reg_out;
shift_register shift_reg_inst (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .shift_direction(shift_direction),
    .load(load),
    .q(shift_reg_out)
);

wire [3:0] count_out;
counter count_inst (
    .clk(clk),
    .reset(reset & select),
    .count(count_out)
);

control_logic control_inst (
    .select(select),
    .shift_reg_out(shift_reg_out),
    .count_out(count_out),
    .active_out(q)
);

