module top_module (
    input [3:0] A, B, C, D,
    input S0, S1, S2,
    output [3:0] Y
);

    wire [3:0] mux_out;
    wire [3:0] shift_out;

    mux_4to1 mux_inst (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .S0(S0),
        .S1(S1),
        .Y(mux_out)
    );

    barrel_shifter barrel_inst (
        .A(mux_out),
        .B({3'b000, S2}),
        .C(shift_out)
    );

    assign Y = shift_out;

endmodule
module mux_4to1 (
    input [3:0] A, B, C, D,
    input S0, S1,
    output reg [3:0] Y
);

    always @*
        case ({S1, S0})
            2'b00: Y = A;
            2'b01: Y = B;
            2'b10: Y = C;
            2'b11: Y = D;
        endcase

endmodule
module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    output [3:0] C
);

    assign C = (B[3]) ? {A[2:0], 3'b000} : 
                        (B[2]) ? {A[1:0], 2'b00, 2'b00} :
                                (B[1]) ? {A[0], 3'b0000} :
                                        A;

