module top_module( 
    input [255:0] in,
    input [7:0] sel,
    input clk,
    input reset,
    output reg [6:0] seg,
    output reg [3:0] an ); 

    // 1-bit, 256-to-1 multiplexer
    wire [7:0] sel_decoded;
    wire [255:0] in_selected;
    assign sel_decoded = {8{sel[7]}};
    assign in_selected = in & (sel_decoded ^ sel);

    // 4-bit binary up counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Functional module
    wire [11:0] out_func;
    assign out_func = in_selected + counter;

    // 7-segment display controller
    reg [15:0] out_hex;
    always @(posedge clk) begin
        out_hex <= out_func;
    end

    // 7-segment display decoder
    reg [3:0] an_decoder;
    always @(out_hex) begin
        case (an_decoder)
            4'b0000: seg = 7'b1000000; // 0
            4'b0001: seg = 7'b1111001; // 1
            4'b0010: seg = 7'b0100100; // 2
            4'b0011: seg = 7'b0110000; // 3
            4'b0100: seg = 7'b0011001; // 4
            4'b0101: seg = 7'b0010010; // 5
            4'b0110: seg = 7'b0000010; // 6
            4'b0111: seg = 7'b1111000; // 7
            4'b1000: seg = 7'b0000000; // 8
            4'b1001: seg = 7'b0010000; // 9
            4'b1010: seg = 7'b0001000; // A
            4'b1011: seg = 7'b0000011; // B
            4'b1100: seg = 7'b1000110; // C
            4'b1101: seg = 7'b0100001; // D
            4'b1110: seg = 7'b0000110; // E
            4'b1111: seg = 7'b0001110; // F
            default: seg = 7'b1111111; // Blank
        endcase
    end

    // 7-segment display multiplexer
    always @(posedge clk) begin
        if (reset) begin
            an_decoder <= 4'b0000;
            an <= 4'b1111;
        end else begin
            an_decoder <= an_decoder + 1;
            case (an_decoder)
                4'b0000: an <= 4'b1110;
                4'b0001: an <= 4'b1101;
                4'b0010: an <= 4'b1011;
                4'b0011: an <= 4'b0111;
                default: an <= 4'b1111;
            endcase
        end
    end

