module up_down_counter (
  input clk,
  input reset,
  input load,
  input control,
  output reg[3:0] count,
  output wire max_reached,
  output wire min_reached
);

  reg [3:0] data;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count <= 4'b0;
    end else if (load) begin
      count <= data;
    end else begin
      if (control) begin
        if (count == 4'b1111) begin
          count <= 4'b0000;
        end else begin
          count <= count + 1;
        end
      end else begin
        if (count == 4'b0000) begin
          count <= 4'b1111;
        end else begin
          count <= count - 1;
        end
      end
    end
  end

  always @(load, control, count) data = control ? (count == 4'b1111 ? 4'b0000 : count + 1) : (count == 4'b0000 ? 4'b1111 : count - 1);

  assign max_reached = (count == 4'b1111);
  assign min_reached = (count == 4'b0000);

