//1011
module vending_machine (
  input clk,
  input reset,
  input coin,
  input item1_button,
  input item2_button,
  input item3_button,
  output reg item1_dispense,
  output reg item2_dispense,
  output reg item3_dispense,
  output reg change_dispense
);

// Define the states of the FSM
parameter IDLE_STATE = 2'b00;
parameter ITEM1_STATE = 2'b01;
parameter ITEM2_STATE = 2'b10;
parameter ITEM3_STATE = 2'b11;

// Define the prices of each item
parameter ITEM1_PRICE = 25;
parameter ITEM2_PRICE = 50;
parameter ITEM3_PRICE = 75;

// Define the maximum amount of money that can be inserted
parameter MAX_AMOUNT = 100;

// Define the current state and amount of money inserted
reg [1:0] state = IDLE_STATE;
reg [7:0] amount = 0;

// Define the outputs
reg change_needed = 0;
reg [7:0] change_amount = 0;

// Define the state transition logic
always @(posedge clk) begin
  if (reset) begin
    state <= IDLE_STATE;
    amount <= 0;
    item1_dispense <= 0;
    item2_dispense <= 0;
    item3_dispense <= 0;
    change_dispense <= 0;
    change_needed <= 0;
    change_amount <= 0;
  end else begin
    case (state)
      IDLE_STATE: begin
        if (item1_button) begin
          state <= ITEM1_STATE;
        end else if (item2_button) begin
          state <= ITEM2_STATE;
        end else if (item3_button) begin
          state <= ITEM3_STATE;
        end
        if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM1_STATE: begin
        if (amount >= ITEM1_PRICE) begin
          item1_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM1_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM2_STATE: begin
        if (amount >= ITEM2_PRICE) begin
          item2_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM2_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM3_STATE: begin
        if (amount >= ITEM3_PRICE) begin
          item3_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM3_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
    endcase
    if (amount > MAX_AMOUNT) begin
      change_needed <= 1;
      change_amount <= amount - MAX_AMOUNT;
      amount <= MAX_AMOUNT;
      state <= IDLE_STATE;
    end
    if (change_needed) begin
      change_dispense <= 1;
      amount <= amount - change_amount;
      change_needed <= 0;
    end else begin
      change_dispense <= 0;
    end
  end
end

endmodule
