                         (h_io_addr == 16'h3c2 & h_iowr) |
                         ins0_rd | ins1_rd |
                         fcr_rd | fcr_wr |
                         (ext_index_hit & (h_io_16 | h_io_8)) |
                         (crt_index_hit & (h_io_16 | h_io_8));

