parameter numOfRam = 32;
parameter delay = 1.5;

parameter EMPTY   = 2'b00;
parameter BETWEEN = 2'b01;
parameter READOUT = 2'b10;
parameter FULL    = 2'b11;

reg    [1:0] state;
reg    [1:0] state_next;

reg    [4:0] head;
reg    [4:0] head_next;
reg    [4:0] tail;
reg    [4:0] tail_next;

