reg		do_pop;
reg		do_push;
reg		do_push_pop;

always @(posedge clk or negedge rst_n) begin
if (rst_n == 0) begin
state <= EMPTY;
head  <= 5'b0;
tail  <= 5'b0;
end else begin
state <= #(delay) state_next;
head  <= #(delay) head_next;
tail  <= #(delay) tail_next;
end
end


always @(*) begin
		do_idle = 1'b0;
		do_pop  = 1'b0;
		do_push = 1'b0;
		do_push_pop = 1'b0;
