				end else if (do_pop) begin
				addr          = tail;
				state_next    = READOUT;
				end else if (do_push && almost_full) begin
				addr          = head;
				head_plus     = 1'b1;
				wen           = 1'b0;
				state_next    = FULL;
				end
				end
				READOUT:  begin
				if (!almost_empty) begin
				tail_plus     = 1'b1;
				error         = (do_push | do_pop);
				state_next    = BETWEEN;
				end else begin
				tail_plus     = 1'b1;
				error         = (do_push | do_pop);
				state_next    = EMPTY;
				end
				end
				FULL:     begin
				if (do_pop) begin
				addr          = tail;
				state_next    = READOUT;
				end else if (do_idle || do_push || do_push_pop) begin
				error         = (do_push | do_push_pop);
				state_next    = FULL;
				end

				end
				endcase
		end
