module CSADD(clk, rst, x, y, ld, sum);
    input clk, rst;
    input x, y;
    input ld;
    output reg sum;

    reg sc;

    // Half Adders logic
    wire hsum1, hco1;
    assign hsum1 = y ^ sc;
    assign hco1 = y & sc;

    wire hsum2, hco2;
    assign hsum2 = x ^ hsum1;
    assign hco2 = x & hsum1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            //Reset logic goes here.
            sum <= 1'b0;
            sc <= 1'b0;
        end
        else if (ld) begin
             sum <= 1'b0;
             sc  <= 1'b0;
        end
        else begin
            //Sequential logic goes here.
            sum <= hsum2;
            sc <= hco1 ^ hco2;
        end
    end
endmodule,"After synthesis, this design has 2 clkinv_1, 2 dfrtp_1, 1 maj3_1, 1 nor2_1, 1 nor2b_1, 1 xnor3_1. ","Area of clkinv_1 is 3.75. Area of dfrtp_1 is 25.02. Area of maj3_1 is 10.01. Area of nor2_1 is 3.75. Area of nor2b_1 is 6.26. Area of xnor3_1 is 22.52.

