module shift_register (
    input CLK,
    input D,
    input RESET,
    output Q
);

    wire Q_temp;

    // D flip-flop
    dff dff (
        .D(D),
        .CLK(CLK),
        .Q(Q_temp)
    );

    // AND gate
    and2 and_gate (
        .A(Q_temp),
        .B(RESET),
        .Z(Q)
    );

endmodule

