          // Read data
          if (!empty) begin
            entries <= entries - 1;
            rd_address <= (rd_address == 1) ? 0 : (rd_address + 1);
          end
        end
        2'd3: begin
          wr_address <= (wr_address == 1) ? 0 : (wr_address + 1);
          rd_address <= (rd_address == 1) ? 0 : (rd_address + 1);
        end
        default: begin
        end
      endcase
    end
  end

  always @(posedge clk) begin
    //Write data
    if (wr & !full) begin
      case (wr_address)
