module barrel_shifter (
    input [7:0] DATA_IN,
    input [1:0] SHIFT,
    output reg [7:0] DATA_OUT
);

always @(*) begin
    case (SHIFT)
        2'b00: DATA_OUT = DATA_IN;
        2'b01: DATA_OUT = DATA_IN >> 1;
        2'b10: DATA_OUT = DATA_IN << 1;
        2'b11: DATA_OUT = {DATA_IN[0], DATA_IN[7:1]};
        default: DATA_OUT = DATA_IN;
    endcase
end

endmodule

module binary_to_bcd (
    input [7:0] binary_in,
    output reg [15:0] bcd_out
);

integer i;

always @(*) begin
    bcd_out = 16'b0;
    for (i = 0; i < 8; i = i + 1) begin
        if (bcd_out[3:0] >= 5) begin
            bcd_out[3:0] = bcd_out[3:0] + 3;
        end
        if (bcd_out[7:4] >= 5) begin
            bcd_out[7:4] = bcd_out[7:4] + 3;
        end
        if (bcd_out[11:8] >= 5) begin
            bcd_out[11:8] = bcd_out[11:8] + 3;
        end
        if (bcd_out[15:12] >= 5) begin
            bcd_out[15:12] = bcd_out[15:12] + 3;
        end
        bcd_out = bcd_out << 1;
        bcd_out[0] = binary_in[7 - i];
    end
end

