module binary_to_bcd (
    input [3:0] binary_in, // Binary input
    output reg [3:0] bcd_high, // BCD output for high digit
    output reg [3:0] bcd_low // BCD output for low digit
);
    always @* begin
        if (binary_in > 4'b1001) begin
            bcd_high = 4'b1;
            bcd_low = binary_in - 4'b1010;
        end else begin
            bcd_high = 4'b0;
            bcd_low = binary_in;
