    if (reset == 1'b1) begin
        counting <= 1'b0;
    end else if (reset_bit_counter == 1'b1) begin
        counting <= 1'b1;
    end else if ((bit_clk_falling_edge == 1'b1) && (bit_counter == 5'h00)) begin
        counting <= 1'b0;
    end
end

