module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] X;
    wire [3:0] C;

    full_adder fa0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .S(X[0]),
        .C(C[0])
    );
    full_adder fa1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(C[0]),
        .S(X[1]),
        .C(C[1])
    );
    full_adder fa2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(C[1]),
        .S(X[2]),
        .C(C[2])
    );
    full_adder fa3 (
