module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output C
);

    wire s1;
    wire c1;
    wire c2;

    xor (s1, A, B);
    xor (S, s1, Cin);
    and (c1, A, B);
    and (c2, s1, Cin);
    or (C, c1, c2);

