//1175

module Adder4(S, Cout, A, B, Cin);
  output [3:0] S;
  output Cout;
  input [3:0] A, B;
  input Cin;

  wire [3:0] sum;
  wire int_0n, int_1n;

  // Full adder for the least significant bit
  FullAdder FA0 (sum[0], int_0n, A[0], B[0], Cin);

  // Full adder for the remaining bits
  FullAdder FA1 (sum[1], int_1n, A[1], B[1], int_0n);
  FullAdder FA2 (sum[2], Cout, A[2], B[2], int_1n);
  FullAdder FA3 (sum[3], , A[3], B[3], Cout);

  assign S = sum;
  assign Cout = Cout;

endmodule
module FullAdder(S, Cout, A, B, Cin);
  output S, Cout;
  input A, B, Cin;

  wire int_0n, int_1n;

  // XOR gate
  xor (int_0n, A, B);

  // AND gate
  and (int_1n, A, B);

  // AND gate
  and (Cout, int_0n, Cin);

  // OR gate
  or (S, int_0n, Cin);

endmodule,"After synthesis, this design has 1 clkinv_1, 1 nand2_1, 1 nor4_1, 1 o21ai_0, 1 o31ai_1, 1 o41ai_1, 4 xnor2_1. ","Area of clkinv_1 is 3.75. Area of nand2_1 is 3.75. Area of nor4_1 is 6.26. Area of o21ai_0 is 5.0. Area of o31ai_1 is 7.51. Area of o41ai_1 is 8.76. Area of xnor2_1 is 8.76.

