module fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);

    parameter DEPTH = 32;
    parameter WIDTH = 32;

    input aclr;
    input [WIDTH-1:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [WIDTH-1:0] q;
    output rdempty;
    output wrfull;

    reg [WIDTH-1:0] fifo [0:DEPTH-1];
    reg [5:0] wr_ptr;
    reg [5:0] rd_ptr;
    wire [5:0] next_wr_ptr;
    wire [5:0] next_rd_ptr;
    wire full;
    wire empty;

    assign wrfull = full;
    assign rdempty = empty;
    assign q = fifo[rd_ptr];

    always @(posedge wrclk or negedge aclr) begin
        if (~aclr) begin
            wr_ptr <= 0;
        end else if (wrreq && ~full) begin
            fifo[wr_ptr] <= data;
            wr_ptr <= next_wr_ptr;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (~aclr) begin
            rd_ptr <= 0;
        end else if (rdreq && ~empty) begin
            rd_ptr <= next_rd_ptr;
        end
    end

    assign full = (wr_ptr == next_rd_ptr);
    assign empty = (wr_ptr == rd_ptr);

    assign next_wr_ptr = {wr_ptr[4:0], wr_ptr[5]} + 1'b1;
    assign next_rd_ptr = {rd_ptr[4:0], rd_ptr[5]} + 1'b1;

