module priority_encoder (
    input [7:0] in,   // 8-bit input for the priority encoder
    output reg [2:0] out // Output from the priority encoder
);

// Binary-to-Gray code converter
wire [7:0] gray_in = in ^ (in >> 1);

// Gray-to-binary code converter
always @(gray_in) begin
    case (gray_in)
        8'b00000001: out = 3'b001;
        8'b00000011: out = 3'b010;
        8'b00000111: out = 3'b011;
        8'b00001111: out = 3'b100;
        8'b00011111: out = 3'b101;
        8'b00111111: out = 3'b110;
        8'b01111111: out = 3'b111;
        default: out = 3'b000;
    endcase
end

endmodule
module d_flip_flop (
    input clk,    // Clock signal
    input d,  // Data input
    output reg q // Output from the D flip-flop
);

// Implementing D flip-flop using NAND gates
wire n1, n2, n3, n4;
assign n1 = ~(d & q);
assign n2 = ~(clk & n1);
assign n3 = ~(q & n2);
assign n4 = ~(clk & n3);
always @(posedge clk) begin
    q <= ~(n4 & q);
end

endmodule
