module fifo #(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 4
)(
    input clk,
    input reset,
    input wr_en,
    input rd_en,
    input [DATA_WIDTH-1:0] wr_data,
    output reg [DATA_WIDTH-1:0] rd_data,
    output not_full,
    output not_empty,
    output error
);

localparam FIFO_SIZE = 1 << ADDR_WIDTH;

reg [DATA_WIDTH-1:0] queue[0:FIFO_SIZE-1];
reg [ADDR_WIDTH-1:0] rd_index = 0;
reg [ADDR_WIDTH-1:0] wr_index = 0;
reg [ADDR_WIDTH:0] count = 0; // Extend count to handle overflow

wire [ADDR_WIDTH-1:0] next_rd_index = rd_index + 1'b1;
wire [ADDR_WIDTH-1:0] next_wr_index = wr_index + 1'b1;

assign not_full = (count < FIFO_SIZE);
assign not_empty = (count > 0);
assign error = (wr_en && !not_full) || (rd_en && !not_empty);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        rd_index <= 0;
        wr_index <= 0;
        count <= 0;
    end
    else begin
        if (wr_en && not_full) begin
            queue[wr_index] <= wr_data;
            wr_index <= next_wr_index;
            count <= count + 1'b1;
        end
        if (rd_en && not_empty) begin
            rd_data <= queue[rd_index];
            rd_index <= next_rd_index;
            count <= count - 1'b1;
        end
    end
end


