					 l = 6'd11,  
					 m = 6'd12,
					 n = 6'd13,
					 o = 6'd14,
					 p = 6'd15,
					 q = 6'd16,
					 r = 6'd17,
					 s = 6'd18,
					 t = 6'd19;

reg [5:0] state_reg, state_next ; always @(posedge CLK, posedge RST_EX)
	if (RST_EX) begin
		state_reg <= a;	
	end
	else begin
		state_reg <= state_next;
	end

always @*
	begin
	state_next = state_reg;

	EN_REG2 = 0;
    EN_REG3 = 0;
    EN_REG4 = 0;
    EN_REG1X = 0;
    EN_REG1Y = 0;
    EN_REG1Z = 0;
    EN_REG2XYZ = 0;
    Begin_SUMX = 0;
    Begin_SUMY = 0;
    Begin_SUMZ = 0;
    Begin_MULT = 0;
    ACK_EX = 0;
    CLK_CDIR = 0;
    RST = 0;
    MS_M = 2'b00;
    MS_1 = 0;
    MS_2 = 2'b00;
    ADD_SUBT = 0;
    EN_ADDSUBT = 0;
