                    state_next = a;
            end

            b:
            begin
                ADD_SUBT = 0;
                EN_ADDSUBT = 1;
                MS_M = 2'b00;
                EN_MS_M = 1;
                MS_1 = 1;
                EN_MS1 = 1;
                MS_2 = 2'b10;
                EN_MS2 = 1;
                state_next = c;
            end

            c:
