                EN_REG2 = 1;
                state_next = j;
            end

            j:
            begin
                EN_REG2XYZ = 1;
                state_next = k;
            end

            k:
            begin
                Begin_SUMX = 1;
                Begin_SUMY = 1;
                CLK_CDIR = 1;
                state_next = l;
            end

            l:
            begin
                state_next = m;
            end

            m:
            begin
