                    EN_REG1X = 1;
                    EN_REG1Y = 1;
                    state_next = n;
                    end
                else
                    state_next = m;
            end

            n:
            begin

                if(ACK_ADD_SUBTZ)
                    begin
                    EN_REG1Z = 1;
                    state_next = o;
                    end
                else
                    state_next = n;
            end

            o:
            begin

