                   EN_REG4 = 1;
                   state_next = t;
                   end
                else
                   state_next = s;    
            end

            t:
            begin
                ACK_EX = 1;
                if(RST_EX)
                    begin 
                    RST = 1; 
                    state_next = a;
                    end
            end
        endcase
end


