    if (reset) begin
        shift_reg <= 8'b0;
        counter <= 4'b0;
    end else begin
        if (select) begin
            shift_reg <= {shift_reg[6:0], d};
        end else begin
            shift_reg <= {d, shift_reg[7:1]};
        end

        ena <= 4'b1111;
        c <= counter;
        counter <= counter + 1;
        if (counter == 4'b1111) begin
            counter <= 4'b0;
        end
    end
end

assign q = shift_reg;
assign f = shift_reg ^ {counter, counter, counter, counter};

