module full_adder_4bit ( A, B, Ci, S, Co );
  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;
  wire [3:0] Cin, Cout;

  assign Cin[0] = Ci;
  assign S[0] = A[0] ^ B[0] ^ Ci;
  assign Cout[0] = (A[0] & B[0]) | (Ci & (A[0] | B[0]));

  assign Cin[1] = Cout[0];
  assign S[1] = A[1] ^ B[1] ^ Cin[1];
  assign Cout[1] = (A[1] & B[1]) | (Cin[1] & (A[1] | B[1]));

  assign Cin[2] = Cout[1];
  assign S[2] = A[2] ^ B[2] ^ Cin[2];
  assign Cout[2] = (A[2] & B[2]) | (Cin[2] & (A[2] | B[2]));

  assign Cin[3] = Cout[2];
  assign S[3] = A[3] ^ B[3] ^ Cin[3];
  assign Cout[3] = (A[3] & B[3]) | (Cin[3] & (A[3] | B[3]));

  assign Co = Cout[3];
endmodule,"After synthesis, this design has 2 a21oi_1, 1 and2_0, 2 maj3_1, 3 nand2_1, 1 nand3_1, 1 nor2_1, 1 nor2b_1, 1 nor3_1, 1 o21ai_0, 1 or2_0, 4 xnor2_1. ","Area of a21oi_1 is 5.0. Area of and2_0 is 6.26. Area of maj3_1 is 10.01. Area of nand2_1 is 3.75. Area of nand3_1 is 5.0. Area of nor2_1 is 3.75. Area of nor2b_1 is 6.26. Area of nor3_1 is 5.0. Area of o21ai_0 is 5.0. Area of or2_0 is 6.26. Area of xnor2_1 is 8.76.

