module top_module (
    input clk,
    input reset,
    input write_en,
    input [7:0] write_addr,
    input [7:0] write_data,
    input read_en,
    input [7:0] read_addr,
    input [7:0] data_input,
    input select_input,
    output [7:0] data_output
);

// using dual-port RAM
reg [7:0] ram[255:0];

// write data to RAM
always @(posedge clk) begin
    if (write_en) ram[write_addr] <= write_data;
end

// read data from RAM
reg [7:0] ram_output;
always @(posedge clk) begin
    if (read_en) ram_output <= ram[read_addr];
end

// D flip-flops
reg [7:0] dff_output;
always @(posedge clk) begin
    dff_output <= data_input;
end

// Adder module
reg [7:0] adder_output;
always @(*) begin
    adder_output = ram_output + dff_output;
end

// Control logic: if select_input is 1, output is adder_output, otherwise ram_output
reg [7:0] data_output_internal;
always @(*) begin
    if (select_input) data_output_internal = adder_output;
    else data_output_internal = ram_output;
end

// assign data_output_internal to data_output
assign data_output = data_output_internal;

endmodule
