    if (w_phase_latch) begin
      r_data <= { i_rx, r_data[7:1] };
    end
  end  always @ (posedge clk_x4 or negedge rst_x) begin
    if (!rst_x) begin
      r_phase <= 2'b00;
    end else begin
      if (r_state == S_IDLE) begin
