      r_state <= S_IDLE;
    end else begin
      case (r_state)
        S_IDLE: begin
          if (i_rx == 1'b0) begin
            r_state <= S_START;
          end
        end  S_START: begin
          if (w_phase_shift) begin
            r_state <= S_BIT0;
          end
        end  S_BIT0: begin
          if (w_phase_shift) begin
            r_state <= S_BIT1;
          end
        end  S_BIT1: begin
          if (w_phase_shift) begin
            r_state <= S_BIT2;
          end
        end  S_BIT2: begin
          if (w_phase_shift) begin
            r_state <= S_BIT3;
          end
        end  S_BIT3: begin
          if (w_phase_shift) begin
            r_state <= S_BIT4;
          end
        end  S_BIT4: begin
          if (w_phase_shift) begin
            r_state <= S_BIT5;
          end
        end  S_BIT5: begin
          if (w_phase_shift) begin
            r_state <= S_BIT6;
          end
        end  S_BIT6: begin
          if (w_phase_shift) begin
            r_state <= S_BIT7;
          end
        end  S_BIT7: begin
          if (w_phase_shift) begin
            r_state <= S_STOP;
          end
