//1334

module top_module (
    input clk,
    input reset,
    input [1:0] sel, // 2-bit input for the decoder
    input [3:0] a, b, // 4-bit inputs for the multiplier
    output [7:0] product, // 8-bit output from the multiplier
    output [15:0] out // 16-bit output from the decoder
);

reg [15:0] decoder_out;
reg [7:0] product; //8 bit output
reg [15:0] out; // 16 bit output 
reg [3:0] multiplier_out;
integer i;

// 4-to-16 decoder
always @ (sel) begin
    case (sel)
        2'b00: decoder_out = 16'b1111111111111110;
        2'b01: decoder_out = 16'b1111111111111101;
        2'b10: decoder_out = 16'b1111111111111011;
        2'b11: decoder_out = 16'b1111111111110111;
    endcase
end

// 4-bit multiplier using shift-and-add method
always @(posedge clk or posedge reset) begin
    if (reset) begin
        product <= 0;
        multiplier_out <= 0;
    end else begin
        multiplier_out <= a;
        for (i = 0; i < 4; i = i + 1) begin
            if (b[i] == 1) begin
                product <= product + multiplier_out;
            end
            multiplier_out <= multiplier_out << 1;
        end
    end
end

// Output from selected decoder output used as the product
always @ (sel) begin
    case (sel)
        2'b00: out <= decoder_out;
        2'b01: out <= decoder_out;
        2'b10: out <= decoder_out;
        2'b11: out <= product;
    endcase
end

