      		N_S=SoltaI;
      end

		SoltaI:	begin
			if(B2==1 && B1==1)
				N_S=Modo1;
		end

      Modo1: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
       		N_S=SoltaM1;
       	else if(B2==0)
         	N_S=SoltaM;
      end

		SoltaM1:	begin
			if(B2==1 && B1==1)
				N_S=Modo2;
		end

      Modo2: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
        	N_S=SoltaM2;
        else if(B2==0)
          N_S=SoltaM;
      end

		SoltaM2:	begin
			if(B2==1 && B1==1)
				N_S=Modo1;
		end

		SoltaM:	begin
			if(B2==1 && B1==1)
				N_S=Dificuldade1;
		end

	  	Dificuldade1: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
	        N_S=SoltaD1;
        else if(B2==0)
          N_S=SoltaD;
      end

		SoltaD1:	begin
			if(B2==1 && B1==1)
				N_S=Dificuldade2;
		end

      Dificuldade2: begin
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
       	  N_S=SoltaD2;
        else if(B2==0)
          N_S=SoltaD;
      end

		SoltaD2:	begin
			if(B2==1 && B1==1)
				N_S=Dificuldade3;
		end

      Dificuldade3: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
          N_S=SoltaD3;
        else if(B2==0)
          N_S=SoltaD;
      end  

		SoltaD3:	begin
			if(B2==1 && B1==1)
				N_S=Dificuldade1;
		end

		SoltaD:	begin
			if(B2==1 && B1==1)
				N_S=Velocidade1;
		end

    	Velocidade1: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
      	  N_S=SoltaV1;
     		else if(B2==0)
          N_S=SoltaV;
      end

		SoltaV1:	begin
			if(B2==1 && B1==1)
				N_S=Velocidade2;
		end

      Velocidade2: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(B1==0)
        	N_S=SoltaV2;
        else if(B2==0)
         	N_S=SoltaV;
      end

		SoltaV2:	begin
			if(B2==1 && B1==1)
				N_S=Velocidade1;
		end

		SoltaV:	begin
			if(B2==1 && B1==1 && B3==1 && B4==1)
				N_S=Gera_Cor;
		end

		  Gera_Cor: begin 
        if(READY==1)
          N_S=Estado_Inicial;
        else if(MOD==0)
          N_S=Acende;
        else if(B1==0 && B2==1 && B3==1 && B4==1)
          N_S=SoltaG;
        else if(B2==0 && B1==1 && B3==1 && B4==1)
          N_S=SoltaG;
        else if(B3==0 && B1==1 && B2==1 && B4==1)
          N_S=SoltaG;
        else if(B4==0 && B1==1 && B3==1 && B2==1)
          N_S=SoltaG;
      end
		SoltaG:	begin
			if(B2==1 && B1==1 && B3 == 1 && B4 == 1 && READY == 1)
				N_S=Acende;
		end
      Acende: begin 
        if(pA>pT)
        	N_S=Input;
        else if(READY)
          N_S=Apaga;
      end
      Apaga: begin 
        if(READY==1)
          N_S=Acende;
      end
	  	Input: begin 
        if(READY==1 && MOD==0)
          N_S=Fim;
        else if(READY==1 && MOD==1)
          N_S=Deathmatch;
        else if(B1==0 && B2==1 && B3==1 && B4==1)
          N_S=Apaga2;
        else if(B2==0 && B1==1 && B3==1 && B4==1)
          N_S=Apaga2;
        else if(B3==0 && B2==1 && B1==1 && B4==1)
          N_S=Apaga2;
        else if(B4==0 && B2==1 && B3==1 && B1==1)
          N_S=Apaga2;
      end
      Apaga2: begin 
        if(READY==1 && MOD==0)
          N_S=Fim;
        else if(READY==1 && MOD==1)
          N_S=Deathmatch;
        else if(B1==1 && B2==1 && B3==1 && B4==1)
          N_S=Compara;
      end
      Compara: begin 
        if(pA>0 && COR==SEQ[pT-pA])
          N_S=Input;
        else if(pA==0 && pT<TMAX-1 && COR==SEQ[pT-pA])
          N_S=Muda_Player;
        else if(COR!=SEQ[pT-pA] && MOD==0)
          N_S=Fim;
        else if(COR==SEQ[pT-pA] && pA==0 && pT==TMAX-1)
          N_S=Fim;
        else if(COR!=SEQ[pT-pA] && MOD==1)
          N_S=Deathmatch;
      end
      Muda_Player: begin 
        if(MOD==0)
          N_S=Gera_Cor;
        else if(READY==1)
          N_S=Gera_Cor;
      end
	  	Deathmatch: begin 
        if(READY==1)
          N_S=AcendeD;
      end
      AcendeD: begin 
        if(pA>pT)
          N_S=InputD;
        else if(READY==1)
          N_S=ApagaD;
      end
      ApagaD: begin 
        if(READY==1)
          N_S=AcendeD;
      end
      InputD: begin 
        if(READY==1)
          N_S=ComparaD2;
        else if(B1==0 && B2==1 && B3==1 && B4==1)
          N_S=ApagaD2;
        else if(B2==0 && B1==1 && B3==1 && B4==1)
          N_S=ApagaD2;
        else if(B3==0 && B2==1 && B1==1 && B4==1)
          N_S=ApagaD2;
        else if(B4==0 && B2==1 && B3==1 && B1==1)
          N_S=ApagaD2;
      end
      ApagaD2: begin 
        if(READY==1)
          N_S=ComparaD2;
        else if(B1==1 && B2==1 && B3==1 && B4==1)
          N_S=ComparaD;
      end
      ComparaD: begin 
        if(COR!=SEQ[pT-pA])
          N_S=ComparaD2;
        else if(pA==0)
          N_S=ComparaD2;
        else if(pA>0)
          N_S=InputD;
      end
      ComparaD2: begin 
        if(pA>pAux && P==1 && READY==1)
          N_S=Fim;
        else if(pA>pAux && P==0 && READY==1)
          N_S=Fim;
        else if(pA<pAux && P==1 && READY==1)
          N_S=Fim;
        else if(pA<pAux && P==0 && READY==1)
          N_S=Fim;
        else if(pA==pAux && READY==1)
          N_S=Fim;
      end
	  	Fim: begin 
        if(READY==1)
          N_S=Resultados;
      end
      Resultados: begin 
        if(B1==0 || B2==0 || B3==0 || B4==0)
          N_S=Aguarda_Input;
      end
      Aguarda_Input: begin 
        if(B1==1 && B2==1 && B3==1 && B4==1)
          N_S=Estado_Inicial;
      end
      default: N_S=Estado_Inicial;
    endcase
	 end
	end


