//1392
module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg C
);

    always @(*) begin
        if (A[3] == 0 && B[3] == 1) // A is positive, B is negative
            C = 1;
        else if (A[3] == 1 && B[3] == 0) // A is negative, B is positive
            C = 0;
        else if (A[3] == 0 && B[3] == 0) // Both A and B are positive
            C = (A >= B) ? 1 : 0;
        else if (A[3] == 1 && B[3] == 1) // Both A and B are negative
            C = (A <= B) ? 1 : 0;
    end

endmodule,"After synthesis, this design has 2 a21oi_1, 1 a31oi_1, 1 clkinv_1, 1 conb_1, 1 dlxtn_1, 1 nand2_1, 2 nand2b_1, 2 nor2b_1, 2 o221ai_1. ","Area of a21oi_1 is 5.0. Area of a31oi_1 is 6.26. Area of clkinv_1 is 3.75. Area of conb_1 is 3.75. Area of dlxtn_1 is 15.01. Area of nand2_1 is 3.75. Area of nand2b_1 is 6.26. Area of nor2b_1 is 6.26. Area of o221ai_1 is 8.76.

