        4'b1100: out_reg <= 16'b0001000000000000;
        4'b1101: out_reg <= 16'b0010000000000000;
        4'b1110: out_reg <= 16'b0100000000000000;
        4'b1111: out_reg <= 16'b1000000000000000;
