module top_module (
    input clk,
    input reset,
    input [3:0] data_in,
    output [3:0] count,
    output gt,
    output lt,
    output eq,
    output [1:0] compare_output
);

    wire [3:0] counter_out;
    wire greater_than;
    wire less_than;
    wire equal;
    wire [1:0] functional_out;

    up_down_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .up_down(greater_than),
        .count_out(counter_out)
    );

    comparator comparator_inst (
        .a(counter_out),
        .b(data_in),
        .greater_than(greater_than),
        .less_than(less_than),
        .equal(equal)
    );

    functional functional_inst (
        .greater_than(greater_than),
        .less_than(less_than),
        .equal(equal),
        .functional_out(functional_out)
    );

    assign count = counter_out;
    assign gt = greater_than;
    assign lt = less_than;
    assign eq = equal;
    assign compare_output = functional_out;

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [3:0] count_out
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count_out <= 4'b0000;
        end else begin
            if (up_down) begin
                count_out <= count_out + 1;
            end else begin
                count_out <= count_out - 1;
            end
        end
    end

endmodule

module comparator (
    input [3:0] a,
    input [3:0] b,
    output greater_than,
    output less_than,
    output equal
);

    assign greater_than = (a > b);
    assign less_than = (a < b);
    assign equal = (a == b);

endmodule

module functional (
    input greater_than,
    input less_than,
    input equal,
    output reg [1:0] functional_out
);

    always @(*) begin
        if (greater_than) begin
            functional_out = 2'b10;
        end else if (less_than) begin
            functional_out = 2'b00;
        end else if (equal) begin
            functional_out = 2'b01;
        end
    end

