  always @(posedge Clk_i, negedge Reset_n_i) begin
    if (!Reset_n_i) begin
      State_r <= IDLE;
    end else begin
      State_r <= NextState_r;
    end
  end

  // Next state logic
  always @(*) begin
    case (State_r)
      IDLE: begin
        if (Start_i) begin
          NextState_r = START;
        end else begin
          NextState_r = IDLE;
        end
      end
      START: begin
        NextState_r = TRANSMIT_BYTE0;
      end
      TRANSMIT_BYTE0: begin
        if (SPI_FIFOFull_i) begin
          NextState_r = TRANSMIT_BYTE0;
        end else begin
          NextState_r = TRANSMIT_BYTE1;
        end
      end
      TRANSMIT_BYTE1: begin
        if (SPI_FIFOFull_i) begin
          NextState_r = TRANSMIT_BYTE1;
        end else begin
          NextState_r = IDLE;
        end
      end
    endcase
  end

  // Counter logic
  always @(posedge Clk_i, negedge Reset_n_i) begin
    if (!Reset_n_i) begin
      Counter_r <= 0;
    end else if (StartTransfer_w) begin
      Counter_r <= ParamCounterPreset_i;
    end else if (Counter_r > 0) begin
      Counter_r <= Counter_r - 1;
    end
  end

  // Start transfer logic
  assign StartTransfer_w = (State_r == START);

  // Byte data logic
  always @(posedge Clk_i, negedge Reset_n_i) begin
    if (!Reset_n_i) begin
      Byte0_r <= 0;
      Byte1_r <= 0;
    end else if (StartTransfer_w) begin
      Byte0_r <= 8'h1A; // Command byte for ADT7310
      Byte1_r <= 8'h00; // Configuration byte for ADT7310
    end
  end

