          next_bitcount = 0;
          next_byteready = 1;
          next_spiByte = {spiByte[6:0], sampled_mosi};
        end
      else
        begin
          next_bitcount = bitcount + 1'b1;
          next_spiByte = {spiByte[6:0], sampled_mosi};
        end
