initial state = READOPCODE;
always @(posedge clk, posedge rst) 
if (rst)  state <= READOPCODE;
else      state <= next_state;

initial opcode = 0;
initial opdata = 0;
always @(posedge clk) 
begin
  bytecount <= next_bytecount;
  opcode    <= next_opcode;
  opdata    <= next_opdata;
  execute   <= next_execute;
end

