	if (byteready)
	  begin
	    next_bytecount = bytecount + 1'b1;
	    next_opdata = {spiByte,opdata[31:8]};
	    if (&bytecount) // execute long command
	      begin
		next_execute = 1'b1;
	  	next_state = READOPCODE;
	      end
	  end
      end
  endcase
end

