module glitch_filter(
   input clk,
   input data_in,
   output reg data_out
);
   reg [1:0] shift_reg;

   always @(posedge clk) begin
      shift_reg <= {shift_reg[0], data_in};
   end

   always @* begin
      if (shift_reg == 2'b01 || shift_reg == 2'b10)
         data_out <= 1'b1;
      else
         data_out <= 1'b0;
   end
