                      rcvr_shiftreg[1] <= DQ_IN;
                   2:
                      rcvr_shiftreg[2] <= DQ_IN;
                   3:
                      rcvr_shiftreg[3] <= DQ_IN;
                   4:
                      rcvr_shiftreg[4] <= DQ_IN;
                   5:
                      rcvr_shiftreg[5] <= DQ_IN;
                   6:
                      rcvr_shiftreg[6] <= DQ_IN;
