                      1:
                         rcvr_shiftreg[1] <= 1'b0;
                      2:
                         rcvr_shiftreg[2] <= 1'b0;
                      3:
                         rcvr_shiftreg[3] <= 1'b0;
                      4:
                         rcvr_shiftreg[4] <= 1'b0;
                      5:
                         rcvr_shiftreg[5] <= 1'b0;
                      6:
                         rcvr_shiftreg[6] <= 1'b0;
                      7:
                         rcvr_shiftreg[7] <= 1'b0;
                    endcase
